class Result {
	int ret; 
	String theResult;
	/** A function's value is a computed number in its raw form (full precision): the calling expression formats it as text. */
	boolean numeric;
}

class ObjResult {
	int cnt;
	OObject obj;
}

class Message {
	String message;
	String param;
	String[] params;
	OObject object;
	boolean idle;
	boolean do_script;
	Runnable action; //スクリプトスレッドで直接実行する組み込み動作(TTalk.runOnScriptThread)
	boolean keep; //エラー・中断・exit to HyperCard でキューが捨てられても残る(クローズボックスで閉じるスタック)
}

class MemoryData {
	TreeSet<String> treeset;
	ArrayList<String> nameList;
	ArrayList<String> valueList;
	/** nameList の名前→位置。変数が多いとき(グローバル変数など)だけ作る。後ろへの追加は次の検索で取り込み、
	 *  nameList の差し替えは参照の違いで分かる。名前を取り除くときは namesRemoved() で捨てる */
	private java.util.HashMap<String,Integer> nameIndex;
	private ArrayList<String> indexedNames;
	private int indexedSize;

	/** nameList の中の lowerName の位置(最初のもの)。無ければ -1 */
	int indexOfName(String lowerName) {
		ArrayList<String> names = nameList;
		int size = names.size();
		if(size < 16){
			for(int i=0; i<size; i++) if(lowerName.equals(names.get(i))) return i;
			return -1;
		}
		synchronized(this){
			if(nameIndex==null || indexedNames!=names || indexedSize>size){
				nameIndex = new java.util.HashMap<String,Integer>(size*2);
				indexedNames = names;
				indexedSize = 0;
			}
			for(; indexedSize<size; indexedSize++) nameIndex.putIfAbsent(names.get(indexedSize), indexedSize);
			Integer i = nameIndex.get(lowerName);
			if(i!=null && i<size && lowerName.equals(names.get(i))) return i;
			if(i==null) return -1;
		}
		//索引が合わない(別のところで並びが変わった)ときは作り直させて、今回は順に探す
		namesRemoved();
		return names.indexOf(lowerName);
	}

	synchronized void namesRemoved() {
		nameIndex = null;
	}
	/** Parsed lines for transient scripts (do/send and message-box scripts), scoped to this invocation. */
	java.util.IdentityHashMap<ArrayList<String>, ParsedTalkLine[]> parsedLines;
	/** Rewritten one-line commands such as add/subtract; bounded for dynamic do strings. */
	java.util.LinkedHashMap<String, ParsedTalkLine> parsedCommands;
	int variableVersion;
	String message;
	String[] params; //とりあえず引数を持っておく
	/** 関数呼び出しで実行中のハンドラ(the params が name(p1,p2) の形になる) */
	boolean isFunction;
	/** このハンドラで global 宣言した変数名。HyperCardではハンドラごとに宣言が必要で、
	 *  宣言していないハンドラからは同名でもローカル変数として扱われる */
	TreeSet<String> globals;
	/** メッセージボックス: HyperCardではメッセージボックスで使う変数(itを含む)はすべてグローバル */
	boolean allGlobal;
	/** Variables (lower-case names) that hold a number as it was computed, not yet formatted: HyperCard keeps numbers
	 *  in variables and applies the numberFormat when they become text (put 1/3 into v / put v*3 = 1) */
	java.util.HashSet<String> rawNumbers;

	boolean seesGlobal(String lowerName) {
		return allGlobal || (globals!=null && globals.contains(lowerName));
	}
}

class ParsedTalkLine {
	final String source;
	final ArrayList<String> words;
	final ArrayList<TTalk.wordType> types;
	final int variableVersion;

	ParsedTalkLine(String source, ArrayList<String> words, ArrayList<TTalk.wordType> types, int variableVersion) {
		this.source = source;
		this.words = words;
		this.types = types;
		this.variableVersion = variableVersion;
	}
}

