	/** is a/is an の右側に来る型名(Script Language Guideの一覧: number/integer/point/rect/date/empty/logical) */
	static boolean isTypeNameForIsA(String word) {
		String w = word.toLowerCase();
		return w.equals("number") || w.equals("integer") || w.equals("point") ||
			w.equals("rect") || w.equals("rectangle") || w.equals("date") || w.equals("logical") ||
			w.equals("bool") || w.equals("boolean") || w.equals("empty");
	}

	//HyperCard 2.4 / J-2.3: "+3", "1e3" are no numbers (is a number is false, "+1" = "1" compares text)
	private static final java.util.regex.Pattern NUMBER_PATTERN =
		java.util.regex.Pattern.compile("^-?(?:[0-9]+\\.?[0-9]*|\\.[0-9]+)$");
	private static final java.util.regex.Pattern INTEGER_PATTERN =
		java.util.regex.Pattern.compile("^-?[0-9]+$");

	/** HyperCardの数値として読める文字列か(前後の空白は無視、マイナス記号と小数点を許す。+ や指数は数ではない) */
	static boolean isNumberString(String value) {
		return value!=null && NUMBER_PATTERN.matcher(value.trim()).matches();
	}

	static boolean isIntegerString(String value) {
		return value!=null && INTEGER_PATTERN.matcher(value.trim()).matches();
	}

	/** x is a <type> の判定。未知の型名ならnull */
	static Boolean isAType(String typeName, String value) {
		String t = typeName.toLowerCase();
		//SANE's INF and NAN are numbers as computed values (HC J-2.3 probe E MathInf: (0/0) is a number, (1/0) is a number),
		//not as text: "INF" / "NAN(004)" is a number = false (probe Umich Inf Text Arith)
		if(t.equals("number")) return isNumberString(value) || value!=null && value.trim().matches("[+-]?(Infinity|NaN)");
		if(t.equals("integer")){
			//HyperCard: 値が整数なら "12.0" も integer
			if(isIntegerString(value)) return true;
			if(!isNumberString(value)) return false;
			try{ double d = Double.parseDouble(value.trim()); return d==Math.rint(d) && !Double.isInfinite(d); }catch(NumberFormatException e){ return false; }
		}
		if(t.equals("empty")) return null; //HyperCard J-2.3は "is a empty" を受け付けない
		if(t.equals("point") || t.equals("rect") || t.equals("rectangle")){
			return isExpressionList(value, t.equals("point") ? 2 : 4);
		}
		if(t.equals("date")) return HCDateTime.parse(value)!=null;
		if(t.equals("logical") || t.equals("bool") || t.equals("boolean")){
			String v = value.trim();
			return v.equalsIgnoreCase("true") || v.equalsIgnoreCase("false");
		}
		return null;
	}

	/** if/repeat while/repeat until/wait until/wait while の条件値。HyperCardは
	 *  true/false 以外を "Expected true or false here" のエラーにする */
	static boolean conditionIsTrue(String value, String context) throws xTalkException {
		if(value!=null){
			if(value.equalsIgnoreCase("true")) return true;
			if(value.equalsIgnoreCase("false")) return false;
		}
		throw new xTalkException("The condition for {0} requires true or false: {1}", context, value);
	}

	static boolean isAdjective(String word) {
		return "long".equals(word) || "short".equals(word) ||
			"abbrev".equals(word) || "abbr".equals(word) || "abbreviated".equals(word) ||
			"english".equals(word); //the English date / the English time
	}

	static int ordinalChunkNumber(String word) {
		if(word==null) return -1;
		switch(word.toLowerCase(Locale.ROOT)){
		case "first": return 1;
		case "second": return 2;
		case "third": return 3;
		case "fourth": return 4;
		case "fifth": return 5;
		case "sixth": return 6;
		case "seventh": return 7;
		case "eighth": return 8;
		case "ninth": return 9;
		case "tenth": return 10;
		default: return -1;
		}
	}

	static boolean isRelativeChunkSpecifier(String word) {
		return ordinalChunkNumber(word)>0 || "last".equalsIgnoreCase(word) ||
			"middle".equalsIgnoreCase(word) || "any".equalsIgnoreCase(word);
	}
	
