	//受け取ったメッセージを実行するスレッド
	public void run() {
		talk = this;
		init();
        this.setName("scriptEngine");
		//setPriority(MAX_PRIORITY);
		
		while(true){
			Message msg = null;
			synchronized (messageList) { 
				if(messageList.size()>0){
					msg = messageList.get(0);
					messageList.remove(0);
				}
			}
			if(msg != null){
				long messageStartTime = System.currentTimeMillis();
				try {
					if(msg.action!=null){
						boolean changeIdle = idle;
						idle = false;
						try{ msg.action.run(); }
						finally{ if(changeIdle) returnToIdle(); }
						continue;
					}
					if(msg.do_script){
						runQueuedScript(msg, messageStartTime);
						continue;
					}
					//idleメッセージはキューに積んだ時点のカードではなく、
					//実際に処理する時点の「現在のカード」に対して送る。
					//そうしないと、キューに積んだ後にカード移動が起きた場合、
					//移動前の古いカードにidleが届いてしまう
					OObject msgTarget = msg.object;
					if(msg.idle && PCARD.pc.stack!=null && PCARD.pc.stack.curCard!=null){
						msgTarget = idleMessageTarget(msg.object, PCARD.pc.stack.curCard);
						if(msgTarget==null) continue;
					}
					//the start-up/open messages queued for a stack's first card go to the card that is current by then (Teka PIM's
					//startUp goes to TCHome; HyperCard sends the open messages that follow to TCHome's card)
					else if(msg.object instanceof OCard && isOpenSequenceMessage(msg.message) && PCARD.pc.stack!=null &&
							PCARD.pc.stack.curCard!=null && PCARD.pc.stack.curCard!=msg.object){
						msgTarget = PCARD.pc.stack.curCard;
					}
					if("startUp".equalsIgnoreCase(msg.message)){ if(startUpSent) continue; startUpSent = true; }
					if(msg.idle) idleMessageRunning = true;
					try{
						if(msg.params!=null) ReceiveMessage(msg.message, msg.params, msgTarget, null, msg.idle);
						else ReceiveMessage(msg.message, msg.param, msgTarget, null, msg.idle);
					}finally{ if(msg.idle) idleMessageRunning = false; }
				} catch (Exception e) {
					e.printStackTrace();
				}
			}
			else{
				/*if(idle==false)*/
				if(PCARD.pc.tool==null && AuthTool.tool==null){
					//暇なときの後始末(カーソル・mouseWithin など)の例外でスクリプトスレッドが終わると、以後どのスクリプトも
					//動かなくなる。部品の一覧が別スレッド(EDT など)で同時に変わったときの例外などはここで受け止める
					try{ returnToIdle(); }
					catch(RuntimeException e){ e.printStackTrace(); }
				}
				//68K externalの外部ウインドウ(XWindoid)はHyperCardのイベントループが暇なときにイベントを受け取る:
				//ここがそれ。開いている間はidleイベントを間隔短く届ける
				if(Xcmd68k.hasSessions()){ Xcmd68k.pump(); this.TalkSleep(15); }
				else if(TXcmd.terazzaAry!=null) this.TalkSleep(50);
				else waitForMessage(50);
			}
		}
	}

	/**
	 * What a click does to a button's hilite before its mouseUp (HyperCard J-2.3, click at): a button of a family becomes the
	 * hilited one, autoHilite or not (Beats Per Minute's openCard clicks its radio buttons, whose autoHilite is false); an
	 * autoHilite check box or radio button toggles; other buttons only flash.
	 */
	/** The hilite a click (click at) leaves (HC J-2.3 probes A Click Hilite / D Click Hilite): a family button becomes the
	 *  hilited one whatever its autoHilite, an autoHilite check box or radio button toggles, others keep theirs */
	static void clickHilite(OButton b){
		if(b.group!=0) b.setHilite(true);
		else if(b.getAutoHilite() && (b.style==9 || b.style==10)) b.setHilite(!b.getHilite());
	}

	/** startUp has gone out (HyperCard sends it once, to the first stack's card) */
	static volatile boolean startUpSent = false;

	/** Where a message queued at idle time goes: one for a card (idle, arrowKey) to the card that is current by then; a part's
	 *  (mouseWithin from OStack.mouseWithinCheck) stays the part's, null when its card was left meanwhile. Sent to the card,
	 *  the target of mouseWithin was the card and Mirage2's "set textSize of the target" failed. */
	static OObject idleMessageTarget(OObject object, OCard cur){
		if(object==null || object instanceof OCard) return cur;
		return object.parent==cur || object.parent==cur.bg ? object : null;
	}

	private static boolean isOpenSequenceMessage(String m){
		return m!=null && (m.equalsIgnoreCase("startUp") || m.equalsIgnoreCase("openStack") || m.equalsIgnoreCase("openBackground") || m.equalsIgnoreCase("openCard"));
	}

	/** キューから取り出したスクリプト(メッセージボックス/メニュー/起動時の go)をこのスレッドで実行する。
	 *  メッセージのハンドラと同じく実行中はビジー(idle=false)にする。以前は idle=true のままだったので、
		 *  起動時の openStack(goToStack 経由)が長く走っている間、カード/ボタン/フィールドのクリックが
		 *  mouseDown/mouseUp としてキューに積まれ、終了後にまとめて届いていた。 */
	void runQueuedScript(Message msg, long messageStartTime) {
		boolean changeIdle = false;
		if(idle){
			idle = false;
			changeIdle = true;
			GUI.forgetClicks();
		}
		try{
			doScriptforMenu(msg.message);
		}catch(xTalkException e){
			//メッセージボックスから直接実行したコマンドのエラー。
			//ハンドラ経由のエラーは既にdoScriptでダイアログが出ている
			if(!(e instanceof ExitToHyperCard) && !lockErrorDialogs && !stop && lastErrorTime < messageStartTime){
				e.printStackTrace();
				if(errorDialogForTest==null){
					java.awt.Toolkit.getDefaultToolkit().beep();
					showScriptErrorDialog(e.getMessage(), msg.message, -1, null, false, false);
				}
			}
		}finally{
			if(changeIdle) returnToIdle();
		}
	}

	private void TalkSleep(int time){ TalkSleepNanos(time*1_000_000L); }

	/** The empty-queue wait of the script thread: returns as soon as a message is queued (CallMessage notifies), at the
	 *  latest after {@code ms}. A fixed 50 ms sleep here delayed every idle, key and click message by up to 50 ms. */
	private static void waitForMessage(int ms){
		synchronized (messageList) {
			if(!messageList.isEmpty()) return;
			try{ messageList.wait(ms); }catch(InterruptedException e){ Thread.currentThread().interrupt(); }
		}
	}

	/** Sleeps until a nanosecond deadline: a 1/60 s frame wait must not gain the 1-2 ms that sleep(ms) overshoots by each time. */
	private void TalkSleepNanos(long nanos){
		//cmd+.による中断をすぐに反映できるよう、一度に全部sleepするのではなく
		//30msずつ小刻みにsleepしてTTalk.stopを確認する。
		long deadline = System.nanoTime() + nanos;
		while(true){
			if(TXcmd.terazzaAry!=null){
				//sleepしてる間にアニメーション実施
				TXcmd.TerazzaAnime();
			}
			//waitの間もHyperCardは外部ウインドウ(XWindoid)にイベントを配る(nullイベントは割り込みコードのあるウインドウだけ)
			if(Xcmd68k.hasSessions()) Xcmd68k.pumpWhileWaiting();

			long left = deadline - System.nanoTime();
			if(left <= 0){
				break;
			}
			java.util.concurrent.locks.LockSupport.parkNanos(Math.min(left, 30_000_000L));
			if (Thread.currentThread().isInterrupted()) {
				break;
			}
			if(TTalk.stop){
				break;
			}
		}
	}
	
	//メニューを実行するときに内部スクリプトを実行する
	public static String doScriptforMenu(String script) throws xTalkException
	{
		if(Thread.currentThread()!=talk){
			CallMessage(script, "", null, false, true);
			return "";
		}
		stop = false;
		Result result=null;
		MemoryData memData = new MemoryData();
		memData.treeset = new TreeSet<String>();
		memData.nameList = new ArrayList<String>();
		memData.valueList = new ArrayList<String>();
		memData.allGlobal = true; //メッセージボックスの変数(itも)はグローバル
		//複数行(パレットボタンのメッセージはif/repeatを含む最大255文字のスクリプト)はdo文と同じく順に実行する
		//メッセージボックスやメニューのメッセージは現在のカードへ送られる: the target はそのカード(HyperCard)。
		//以前はtargetが無く、Myst Previewのon goの「get the short name of the target」がメニュー(Main Menu/Quit)から
		//送ったgoでエラーになった
		OObject card = PCARD.pc!=null && PCARD.pc.stack!=null ? PCARD.pc.stack.curCard : null;
		if(script.indexOf('\n')>=0 || script.indexOf('\r')>=0){
			result = talk.doScript(null, card, "", script, memData, null, 1);
		}
		else result = talk.doScriptLine(script, /*PCARD.pc.stack.curCard*/null, card, memData, 0);
		
		if(result == null) return "";
		if(result.ret==-1) cancelPendingMessages();
		return result.theResult;
	}
	
	//メッセージをスクリプトスレッドに投げる
	public static void CallMessage(String message, OObject object)
	{
		//System.out.println("CallMessage "+message+" "+object.getShortName());
		if("mouseDown".equals(message)) resetFindResume(); //a user's click: the next find starts at the top
		CallMessage(message, "", object, false, false);
	}
	
	public static void CallMessage(String message, String param, OObject object, boolean idle, boolean do_script)
	{
		if(idle && idleMessagesSuppressed){
			idlePending = false;
			return;
		}
		//mouseWithin waits after an error dialog as idle does: an error in a mouseWithin handler (sent again as soon as the
		//handler ends while the pointer stays on the part) brought the dialog back at once and the stack could not be quit (Mirage2)
		if("mouseWithin".equals(message) && System.currentTimeMillis() < idleResumeTime) return;
		if(!idle) idleMessagesSuppressed = false;
		Message msg = new Message();
		msg.message = message;
		msg.object = object;
		msg.param = param;
		msg.idle = idle;
		msg.do_script = do_script;

		synchronized (messageList) { 
			messageList.add(msg);
			messageList.notifyAll(); //待っているスクリプトスレッドをすぐ起こす
		}
	}

	/**
	 * the mouseClick inside an idle handler: a click made meanwhile was queued as mouseDown/mouseUp (idle stays true while
	 * idle messages are handled), and HyperCard's mouseClick takes it from its event queue - no mouseDown/mouseUp follows.
	 * HyperBird's title card loops "repeat until the mouseClick" in its idle handler and never ended. A press still held is
	 * waited for (as {@link GUI#takeHeldPress}).
	 */
	static boolean takeQueuedClick(){
		if(!idleMessageRunning || !idle || Thread.currentThread()!=talk) return false;
		Message down;
		synchronized (messageList) {
			down = firstClickMessage("mouseDown");
			if(down==null) return false;
		}
		long limit = System.currentTimeMillis()+20000; //a release the window never heard of must not hang the script
		while(GUI.mouseDown && !stop && System.currentTimeMillis()<limit){
			try{ Thread.sleep(10); }catch(InterruptedException e){ Thread.currentThread().interrupt(); break; }
		}
		//the release queues mouseUp right after GUI.mouseDown goes false (a press that moved sends none from the card)
		long upLimit = System.currentTimeMillis()+300;
		while(true){
			synchronized (messageList) {
				int at = messageList.indexOf(down);
				Message up = null;
				for(int i=at+1; at>=0 && i<messageList.size(); i++){
					if(isClickMessage(messageList.get(i), "mouseUp")){ up = messageList.get(i); break; }
				}
				if(up!=null || System.currentTimeMillis()>=upLimit){
					int end = up!=null ? messageList.indexOf(up) : at;
					for(int i=end; at>=0 && i>=at; i--){
						Message m = messageList.get(i);
						if(m==down || m==up || isClickMessage(m, "mouseStillDown") || isClickMessage(m, "mouseDoubleClick")) messageList.remove(i);
					}
					return true;
				}
			}
			try{ Thread.sleep(5); }catch(InterruptedException e){ Thread.currentThread().interrupt(); return true; }
		}
	}

	private static Message firstClickMessage(String name){
		for(Message m : messageList) if(isClickMessage(m, name)) return m;
		return null;
	}

	private static boolean isClickMessage(Message m, String name){
		return m.action==null && !m.do_script && !m.idle && name.equalsIgnoreCase(m.message);
	}

	static void requestUserAbort()
	{
		//cantAbort が true のスタックでは Command-. でハンドラを止められない
		if(PCARD.pc!=null && PCARD.pc.stack!=null && PCARD.pc.stack.cantAbort) return;
		stop = true;
		idleMessagesSuppressed = true;
		synchronized (messageList) {
			messageList.removeIf(message -> message.idle);
		}
		idlePending = false;
	}

	/** The card window was closed while a handler runs: the handlers end as with Command-period, cantAbort or not (the
	 *  window is gone, nothing of the stack is left to see). The close itself is queued behind with keep. */
	static void abortForStackClose()
	{
		stop = true;
		idleMessagesSuppressed = true;
		synchronized (messageList) {
			messageList.removeIf(message -> message.idle);
		}
		idlePending = false;
	}

	static void requestTrace()
	{
		stepflag = false;
		tracemode = 2;
		ScriptDebugger.resetStepDepth();
	}

	/** Queues a built-in action to run on the script thread after the messages already queued, with no message sent
	 *  (the card window's close box: HyperCard closes the stack without a doMenu the stack could catch). */
	static void runOnScriptThread(Runnable action)
	{
		runOnScriptThread(action, false);
	}
	/** The same; with keep it stays queued when the running handlers end in an error, an abort or exit to HyperCard
	 *  (each of which throws the pending messages away). */
	static void runOnScriptThread(Runnable action, boolean keep)
	{
		Message msg = new Message();
		msg.action = action;
		msg.params = new String[0];
		msg.keep = keep;
		synchronized (messageList) {
			messageList.add(msg);
			messageList.notifyAll(); //待っているスクリプトスレッドをすぐ起こす
		}
	}

	/** Queues the mouseUp of a button or locked field whose mouseDown handler was still running at the release (HyperCard sends
	 *  it after that handler). Dropped when the part has left the screen by then (the mouseDown handler went to another card). */
	static void callPendingMouseUp(OObject btn)
	{
		runOnScriptThread(() -> {
			if(!GButton.onCurrentCard(btn)) return;
			try{ talk.ReceiveMessage("mouseUp", "", btn, null, false); }
			catch(xTalkException e){ /* the error dialog was shown */ }
		});
	}

	public static void CallMessage(String message, String[] params, OObject object)
	{
		idleMessagesSuppressed = false;
		Message msg = new Message();
		msg.message = message;
		msg.object = object;
		msg.params = params==null ? new String[0] : params.clone();
		msg.idle = false;
		msg.do_script = false;

		synchronized (messageList) {
			messageList.add(msg);
			messageList.notifyAll(); //待っているスクリプトスレッドをすぐ起こす
		}
	}
	
	private void ReceiveMessage(String message, String param, OObject object, MemoryData memData, boolean idlenow)
	throws xTalkException
	{
		boolean changeIdle=false;
		if(idlenow==false && idle==true){
			//ビジー状態にする
			idle=false;
			changeIdle=true;
			GUI.forgetClicks();
		}

		String[] params;
		if(param != null && !param.isEmpty()){
			params = new String[1];
			params[0] = param;
		}
		else params = new String[0];
		try{
			lastResult = ReceiveMessage(message,params,object,object,memData);
			if(lastResult!=null && lastResult.ret==-1) cancelPendingMessages();
		}finally{
			//idleメッセージの処理が完了した(カード移動等が済んだ)ので、
			//次のidleメッセージを積めるようにする
			if(idlenow) idlePending = false;
		}

		if(changeIdle){
			//idle状態に戻す
			returnToIdle();
		}
	}

	/** テスト用: キューに積まれたメッセージ(openPaletteなど)をこのスレッドでその場で配る */
	static void processPendingMessagesForTest() throws Exception {
		TTalk t = new TTalk();
		while(true){
			Message msg;
			synchronized (messageList) { if(messageList.isEmpty()) break; msg = messageList.remove(0); }
			if(msg.do_script || msg.idle) continue;
			if(msg.action!=null){ msg.action.run(); continue; } //a built-in action (a palette's close box)
			//カードウインドウのないテストなのでidleへ戻る処理(マウス判定)は通さない
			if(msg.params!=null) t.ReceiveMessage(msg.message, msg.params, msg.object, msg.object, null);
			else t.ReceiveMessage(msg.message, new String[]{msg.param}, msg.object, msg.object, null);
		}
	}

	private void ReceiveMessage(String message, String[] params, OObject object,
		MemoryData memData, boolean idlenow) throws xTalkException
	{
		boolean changeIdle=false;
		if(!idlenow && idle){
			idle=false;
			changeIdle=true;
			GUI.forgetClicks();
		}
		lastResult = ReceiveMessage(message, params, object, object, memData);
		if(lastResult!=null && lastResult.ret==-1) cancelPendingMessages();
		if(changeIdle) returnToIdle();
	}

	private static boolean isMillisecondWord(String w){
		return w.equalsIgnoreCase("milliseconds")||w.equalsIgnoreCase("millisecond")||w.equalsIgnoreCase("millisecs")||w.equalsIgnoreCase("millisec")||w.equalsIgnoreCase("ms");
	}

	private static long waitNanos(String value, double unitMillis) throws xTalkException {
		double v;
		if(value.trim().isEmpty()) return 0; //wait empty ticks: HyperCard J-2.3 は待たずに続ける(Internet Tour: wait waitTicks ticks)
		try{ v = Double.parseDouble(value.trim()); }
		catch(NumberFormatException e){ throw new xTalkException("The wait duration is not a number: {0}", value); }
		if(v<0) return 0; //wait (h+a) div 15 with the mouse left of the picture (early works "avenue"): HyperCard does not wait
		return Math.round(v*unitMillis*1_000_000.0);
	}

	//exit to HyperCard は実行中のハンドラ階層だけでなく、キューに積まれた
	//未処理のメッセージ(pending messages)も取り消す(HyperTalk Reference)。
	//idleは次のループで積み直されるので、まとめて消してよい。
	static void cancelPendingMessages()
	{
		synchronized (messageList) {
			messageList.removeIf(message -> !message.keep);
		}
		idlePending = false;
		exitingToHyperCard = false;
	}
	/** A function did exit to HyperCard: the statements still running end (see {@link ExitToHyperCard}); cleared at the top. */
	static volatile boolean exitingToHyperCard;

	/** 閉じたスタックの部品/カード宛てに残っているメッセージ(idle、クリック等)を捨てる。
	 *  閉じた後に届くと、スクリプトが「cd "x" of this stack」を引けずにエラーになる。
	 *  キューに積まれたスクリプト(open stack 等)はスタックに属さないので残す */
	static void dropMessagesFor(OStack stack)
	{
		if(stack==null) return;
		synchronized (messageList) {
			messageList.removeIf(message -> message.idle || (!message.do_script && stackOf(message.object)==stack));
		}
		idlePending = false;
	}

	/** オブジェクトの属するスタック(親をたどる)。スタック外/nullなら null */
	private static OStack stackOf(OObject object)
	{
		for(OObject o = object; o!=null; o = o.ownerObject()){
			if(o instanceof OStack) return (OStack)o;
			if(o instanceof OCardBase) return ((OCardBase)o).stack;
		}
		return null;
	}

	/** Whether the script running lock screen also unlocks with a visual effect. Most changes made under a lock keep
	 *  the parts as they were until the unlock, but a picture drawn into the card by the script would already be in the
	 *  parts when the effect needs the screen from before the lock, so such scripts take the picture at once. */
	private static boolean unlocksWithEffect(OObject object){
		if(object==null || object.scriptList==null) return false;
		ArrayList<String> lines = object.scriptList;
		if(lines.isEmpty()) return false;
		String first = lines.get(0), last = lines.get(lines.size()-1);
		synchronized(unlockEffectScripts){
			Object[] known = unlockEffectScripts.get(lines);
			if(known!=null && (Integer)known[0]==lines.size() && known[1]==first && known[2]==last) return (Boolean)known[3];
		}
		boolean found = false;
		for(String line : lines){
			String l = line.toLowerCase(Locale.ROOT);
			int at = l.indexOf("unlock");
			if(at>=0 && l.indexOf("screen", at)>=0 && l.indexOf(" with", at)>=0){ found = true; break; }
		}
		synchronized(unlockEffectScripts){
			if(unlockEffectScripts.size()>256) unlockEffectScripts.clear();
			unlockEffectScripts.put(lines, new Object[]{lines.size(), first, last, found});
		}
		return found;
	}

	private static long lastExplicitGc = System.nanoTime()-60_000_000_000L;

	private static void returnToIdle(){
		boolean finishedHandler = !idle; //ハンドラの終了(busy→idle)か、単なるidle中の定期呼び出しか
		if(finishedHandler) exitingToHyperCard = false;
		//ハンドラの終わりの明示的なGCは全スレッドを止める(数十ms)。キーを押し続けて1キーごとにハンドラが走るゲームでは
		//毎回のGCが引っかかりになるので、30秒に1回までにする
		if(!idle && !GUI.mouseDown && System.nanoTime()-lastExplicitGc > 30_000_000_000L){
			lastExplicitGc = System.nanoTime();
			SwingUtilities.invokeLater(new Runnable() {
				public void run() {
					java.lang.System.gc();//GCをなるべく呼ぶ
				}
			});
		}
		idle=true;
		TTalk.stop = false;
		TTalk.tracemode = 0;
		if(PCARD.pc.stack==null) return;
		
		lockScreenDepth = 0;
		if(PCARD.lockedScreen){
			//ハンドラ終了時の暗黙unlock。カードをremoveAll/addし直す旧実装は
			//スクリプトスレッドからSwingツリーを再構築して描画競合を起こすため、
			//現在の部品状態をEDT上で一度だけ確定描画する。
			applyDeferredMenuBar();
			VEffect.visualEffect(0, 0, 3);
		}
		//ハンドラごとの状態(visual effectの予約・numberFormat・itemDelimiter・lockMessages)は
		//ハンドラが終わったときだけ初期化する(idle中の定期呼び出しでは触らない)
		if(finishedHandler){
			pendingVisuals.clear(); //使われなかった visual effect の予約は捨てる
			//numberFormatが変えられていたときだけ作り直す
			//(DecimalFormatSymbolsの生成はロケールデータの読み込みを伴い、遅いCPUでは目立つ)。
			if(!DEFAULT_NUMBER_FORMAT.equals(numberFormatPattern)){
				numberFormatPattern = DEFAULT_NUMBER_FORMAT;
				numFormat = DEFAULT_NUMBER_FORMAT_INSTANCE;
			}
			itemDelimiter=",";
			//lockMessages / lockErrorDialogs はハンドラがすべて終わると false に戻る(lockScreenと同様)
			lockMessages = false;
			if(errorDialogForTest==null) lockErrorDialogs = false; //テストではダイアログ抑止のため保持する
		}
		dragspeed = 0;
		//while the mouse is still down after a mouseDown handler HyperCard tracks the click (mouseStillDown) and is not idle: the
		//cursor the handler set stays until the button comes up (OxSetCCursor's colour cursor went back to the hand at once)
		if(!GUI.mouseDown) resetIdleCursor();
		else cursorHeldByPress = true; //GUI.mouseUped puts the browse cursor back
		if(PCARD.pc.mainPane!=null) PCARD.pc.mainPane.releaseHeldCursor(); //a script's choose tool shows its cursor now
		PCARD.pc.stack.mouseWithinCheck();

		ScriptDebugger.reset();
		//open file したファイルはHyperCardと同様に close file するまで開いたままにする
		//(以前はハンドラ終了のたびに全部閉じていたので、別のハンドラから read できなかった)
	}
	

	/** The cursor a mouseDown handler set waits for the mouse-up ({@link #returnToIdle}). */
	static volatile boolean cursorHeldByPress;
	/** HyperCard's browse cursor at idle: the stack's CURS 128 when it has one. */
	static void resetIdleCursor() {
		cursorHeldByPress = false;
		if(PCARD.pc==null || PCARD.pc.stack==null) return;
		Cursor cr = TUtil.browseCursor(); //スタックの CURS 128 があればそれ(HyperCard のブラウズカーソル)
		if(PCARD.pc.getCursor()!=cr) PCARD.pc.setCursor(cr);
	}

	/** スクリプトのハンドラ行を拾って handlerList / handlerLineList を作る(未作成のときだけ) */
	static void ensureHandlerList(OObject object) {
		//both lists: setScript on another thread (the editor's Save, the EDT) clears handlerList before handlerLineList
		if(object==null || object.scriptList==null || object.handlerLineList!=null && object.handlerList!=null) return;
		//継続行(¬)の連結はハンドラ行の位置を1行ずらす(連結後の行が後ろに置かれる)ので、行番号表を作る前に済ませておく。
		//以前は最初のハンドラ実行時に連結していたため、"on kaishi kd1,¬" のように on 行自体が継続する
		//ハンドラは表の行番号がずれて見つからなくなっていた
		if(!object.wrapFlag){
			joinContinuationLines(object.scriptList);
			object.wrapFlag = true;
		}
		//built aside and set at the end: a script set meanwhile (null lists) made the add below a NullPointerException
		TreeSet<String> handlers = new TreeSet<String>();
		ArrayList<Integer> handlerLines = new ArrayList<Integer>();
		java.util.Map<String,String> marked = null;
		java.util.List<String> script = object.scriptList;
		//an AppleScript (OSA) object script is never run: no handlers, messages pass on through the object, as in HyperCard
		//without the AppleScript extension (OsaScript)
		for(int line=0; object.osaScript==null && script!=null && line<script.size(); line++){
			String[] words = splitScriptWords(script.get(line));
			if(words.length<=1){
				continue;
			}
			if( words[0].equalsIgnoreCase("on") ||
				words[0].equalsIgnoreCase("function") ||
				words[0].equalsIgnoreCase("end"))
			{
				if(words[0].equalsIgnoreCase("on") ||
						words[0].equalsIgnoreCase("function") )
				{
					if(words[1].indexOf("--")>=0){
						words[1] = words[1].substring(0,words[1].indexOf("--"));
					}
					String name = words[1].toLowerCase().intern();
					handlers.add(name);
					String plain = withoutMarks(name);
					if(plain!=name){
						if(marked==null) marked = new java.util.HashMap<String,String>();
						marked.putIfAbsent(plain, name);
					}
				}
				handlerLines.add(line);
			}
		}
		object.markedHandlers = marked;
		object.handlerLineList = handlerLines;
		object.handlerList = handlers;
	}

	/** The handler of {@code object} whose name is the message's but for diacritical marks (lower case), or null: DL_MenüPal
	 *  runs on DL_MenuPal and the other way round (HyperCard 2.4 on a Roman system, probe Hcde Err Umlaut Call; marksIgnored) */
	private static String handlerWithoutMarks(OObject object, TreeSet<String> handlers, String message) {
		String key = message.toLowerCase();
		String plain = withoutMarks(key);
		if(plain!=key && handlers.contains(plain)) return plain;
		java.util.Map<String,String> marked = object.markedHandlers;
		return marked!=null ? marked.get(plain) : null;
	}

	/** ハンドラ行(on/function/end)の単語。2番目の単語の "--" 以降は除いてある。メッセージのたびに全ハンドラ行を
	 *  分割し直さないよう、行の String が同じあいだは OObject.controlCache に覚えておく(キーは -1-行番号) */
	private static String[] handlerLineWords(OObject object, int line) {
		String text = object.scriptList.get(line);
		java.util.concurrent.ConcurrentHashMap<Integer,Object> cache = object.controlCache;
		Object cached = cache==null ? null : cache.get(-1-line);
		if(cached instanceof HandlerLineWords h && h.text==text) return h.words;
		String[] words = splitScriptWords(text);
		if(words.length>1 && words[1].indexOf("--")>=0){
			words[1] = words[1].substring(0,words[1].indexOf("--"));
		}
		if(cache==null) object.controlCache = cache = new java.util.concurrent.ConcurrentHashMap<Integer,Object>();
		cache.put(-1-line, new HandlerLineWords(text, words));
		return words;
	}

	private record HandlerLineWords(String text, String[] words) {}

	/** The next object up the static path: a button, field or shape in a panel → the panel, otherwise the parent. */
	static OObject nextInPath(OObject obj){
		OPanel panel = obj.parent instanceof OCardBase ? ((OCardBase)obj.parent).panelOf(obj) : null;
		return panel!=null ? panel : obj.parent;
	}

	/** An object of a stack that is no longer the open one (it was closed while a handler of it ran). */
	private static boolean isStaleObject(OObject o){
		OObject x = o;
		for(int guard=0; x!=null && guard<16; guard++){
			if(x instanceof OStack) return x!=PCARD.pc.stack;
			if(x instanceof OCardBase) return ((OCardBase)x).stack!=PCARD.pc.stack;
			x = x.parent;
		}
		return true;
	}

	private Result ReceiveMessage(String message, String[] params, OObject object, OObject target, MemoryData memData)
	throws xTalkException
	{
		//System.out.println("ReceiveMessage "+message+" "+object.getShortName());
		return receiveFrom(message, params, object, target, memData, false);
	}

	/** Sends a message or function call whose path starts at object (the running handler's object, or the receiver of a send) */
	private Result receiveFrom(String message, String[] params, OObject object, OObject target, MemoryData memData, boolean isFunc)
	throws xTalkException
	{
		OObject outer = messagePathStart;
		boolean outerOff = messagePathStartOff;
		OCard outerCard = messageSendCard;
		messagePathStart = object;
		OCard current = PCARD.pc!=null && PCARD.pc.stack!=null ? PCARD.pc.stack.curCard : null;
		messagePathStartOff = current!=null && startsOff(object, current);
		messageSendCard = current;
		try{
			return ReceiveMessage(message, params, object, target, memData, new Result(), isFunc, false, false, 0);
		}finally{
			messagePathStart = outer;
			messagePathStartOff = outerOff;
			messageSendCard = outerCard;
		}
	}

	/** A stack outside the current hierarchy whose message went on to the current card's path: skipped among the stacks in use */
	private OObject dynamicPathSkip;
	/** Where the message being passed along started (the handler's object for a handler call), for the dynamic path */
	private OObject messagePathStart;
	/**
	 * Whether that start was off the current card's hierarchy when the message was sent. A handler that goes to another
	 * card and then passes its message does not send it on to the new current card: artGallery's openStack goes to card
	 * 4098, paints there and passes openStack, which went to card 4098, its background and the stack again, ran the whole
	 * openStack a second time and its pencil strokes, drawn over their own black ends, erased the first ones.
	 */
	private boolean messagePathStartOff;
	/** The current card when that message was sent: whether its target was off the current card is decided then, too */
	private OCard messageSendCard;

	String[] messageRingArray = new String[128];
	OObject[] objectRingArray = new OObject[128];
	int ringCnt;

	private static final String[] NO_WORDS = new String[0];

	//line.strip().split("[\\s\\u3000]+") と同じ結果を、正規表現を使わずに作る(ハンドラ探索や repeat の終わり探しで行ごとに呼ばれる)
	static String[] splitScriptWords(String line) {
		if(line == null) return NO_WORDS;
		String trimmed = line.strip();
		int length = trimmed.length();
		if(length == 0) return NO_WORDS;
		int count = 0;
		boolean inWord = false;
		for(int i=0; i<length; i++){
			boolean separator = isScriptWordSeparator(trimmed.charAt(i));
			if(!separator && !inWord) count++;
			inWord = !separator;
		}
		if(count == 1) return new String[]{ trimmed };
		String[] words = new String[count];
		int n = 0;
		int from = -1;
		for(int i=0; i<=length; i++){
			boolean separator = i==length || isScriptWordSeparator(trimmed.charAt(i));
			if(!separator){ if(from < 0) from = i; }
			else if(from >= 0){ words[n++] = trimmed.substring(from, i); from = -1; }
		}
		return words;
	}

	//正規表現の \s(空白・タブ・改行・VT・FF・CR)と全角スペース
	private static boolean isScriptWordSeparator(char c) {
		return c==' ' || c=='\t' || c=='\n' || c=='\u000B' || c=='\f' || c=='\r' || c=='\u3000';
	}
	
	//メッセージを受け取る
	private final Result ReceiveMessage(String message, String[] params, OObject object, OObject target, MemoryData memData, Result result, boolean isFunc, boolean isDynamic, boolean isBgroot, int usingCnt)
	throws xTalkException
	{
	    //long timestart = System.currentTimeMillis();
		if(MSG_PATH_TRACE) System.err.println("[path] "+message+" -> "+(object==null?"null":object.objectType+" "+object.getShortName()+(object.parent==null?"":" (parent "+object.parent.objectType+" "+object.parent.getShortName()+")"))+" dyn="+isDynamic+" using="+usingCnt);

		result.ret=1;
		
		if(object == null && PCARD.pc!=null && PCARD.pc.stack!=null){
			object = PCARD.pc.stack.curCard;
		}
		//a handler goes on after its stack was closed and opened again ("go home"/"go back" from AnimationMaker's AMLoad
		//XCMD): its objects are the closed stack's, without scripts now, so its messages start at the current card
		if(object!=null && object.scriptList==null && PCARD.pc!=null && PCARD.pc.stack!=null && PCARD.pc.stack.curCard!=null &&
				object!=PCARD.pc.stack.curCard && isStaleObject(object)){
			//a handler of the stack that was left calls one of its own functions/handlers (HyperCard: the message goes to
			//me first): the closed stack's script still answers it
			boolean own = false;
			if(object.retiredScriptList!=null){
				object.scriptList = object.retiredScriptList;
				ensureHandlerList(object);
				own = object.handlerList!=null && object.handlerList.contains(message.toLowerCase());
				if(!own){ object.scriptList = null; object.handlerList = null; object.handlerLineList = null; }
			}
			//the closed stack's own externals still answer, as the message passes that stack (HC J-2.3 finds the running
			//handler's stack's externals, see TXcmd.CallExternalCommandOf): UxCardToPICS's "Other stack" button goes to the
			//target stack and calls its UxCardToPICS there ("uxcardtopicsがわかりません")
			if(!own && !isDynamic && usingCnt==0 && object instanceof OStack && TXcmd.has68kExternal((OStack)object, message, isFunc ? "function" : "command")){
				messageReachedSystem = true;
				return TXcmd.CallExternalCommandOf((OStack)object, message, params, target, memData, isFunc, result);
			}
			if(!own) object = PCARD.pc.stack.curCard;
		}

		if(object==null || object.scriptList == null){
			//スクリプトを持つオブジェクトが無い(テスト実行等)場合でも、組み込みの
			//コマンド/関数は解決できるようにする
			if(object==null && !commandSet.contains(message)){
				result = TUtil.CallSystemMessage(message, params, target, memData, isFunc);
			}
			return result;
		}
		
		//ハンドラ行のみをピックアップしてリストに保存する
		ensureHandlerList(object);

		//ハンドラを探す (the set read once: a script set meanwhile on another thread empties the object's lists; that was a
		//NullPointerException that lost the message)
		TreeSet<String> handlers = object.handlerList;
		//a Roman stack's handler names match without their marks: the message takes the handler's own name
		if(handlers!=null && !handlers.contains(message.toLowerCase()) && marksIgnored()){
			String same = handlerWithoutMarks(object, handlers, message);
			if(same!=null) message = same;
		}
		if(handlers!=null && handlers.contains(message.toLowerCase())){
			if(message.equalsIgnoreCase("idle")) idleHandlerAt = System.nanoTime();
			//messageWatcher用
			messageRingArray[ringCnt%128] = message;
			objectRingArray[ringCnt%128] = object;
			ringCnt++;
			if(MessageWatcher.watcherWindow!=null && MessageWatcher.watcherWindow.isVisible()){
				MessageWatcher.watcherWindow.setTable(messageRingArray, objectRingArray, ringCnt);
			}
			
			int start=0;
			for(int i=0; object.handlerLineList!=null && i<object.handlerLineList.size(); i++){
				int line=object.handlerLineList.get(i);
				String[] words = handlerLineWords(object, line);
				if(words.length<=1){
					line++;
					continue;
				}
				
				if(words[1].indexOf("--")>=0){
					words[1] = words[1].substring(0,words[1].indexOf("--"));
				}
				
				if(0==words[1].compareToIgnoreCase(message)){
					if(!isFunc && words[0].equalsIgnoreCase("on")){
						start=line+1;
					}
					if(isFunc && words[0].equalsIgnoreCase("function")){
						start=line+1;
					}
					if(start>0 && words[0].equalsIgnoreCase("end")){
						MemoryData memData2 = new MemoryData();
						memData2.treeset = new TreeSet<String>();
						memData2.nameList = new ArrayList<String>();
						memData2.valueList = new ArrayList<String>();
		
						//引数
						String[] rawArgs = rawArgsFor(params);
						String[] handlerWords = handlerLineWords(object, start-1);
						if(handlerWords.length >= 3){ //on handler param
							String paramStr="";
							for(int k=2;k<handlerWords.length;k++) paramStr += handlerWords[k];
							//a comment after the parameters may hold commas and quotes:
							//function conFFrom x  -- from "a/b" to "a,b" (also for matrices) (Math Stack)
							if(paramStr.indexOf("--")>=0) paramStr = paramStr.substring(0, paramStr.indexOf("--"));
							String[] paramNames = paramStr.isEmpty() ? new String[0] : paramStr.split(",");
							for(int j=0; j<paramNames.length; j++){
								if(paramNames[j].startsWith("--")) break;
								if(paramNames[j].indexOf("--")>=0) {
									paramNames[j] = paramNames[j].substring(0,paramNames[j].indexOf("--"));
								}
								paramNames[j] = parameterName(paramNames[j]);
								checkVariableName(paramNames[j].trim());
								if(j >= params.length) setVariable(memData2, paramNames[j], "");
								else if(rawArgs!=null && j<rawArgs.length && rawArgs[j]!=null){
									//a computed number keeps its precision in the parameter, as in a variable (putComputedValue)
									setVariable(memData2, paramNames[j], rawArgs[j]);
									if(memData2.rawNumbers==null) memData2.rawNumbers = new java.util.HashSet<String>();
									memData2.rawNumbers.add(paramNames[j].trim().toLowerCase(Locale.ROOT));
								}
								else setVariable(memData2, paramNames[j], params[j]);
							}
						}
						
						//memDataにメッセージ名とparamsをセット(param(i)とthe paramsのため)。
						//名前はハンドラ定義の綴り(大文字小文字)で持つ: HyperCardのthe params/param(0)は
						//小文字化されない
						memData2.message = words[1];
						memData2.params = params;
						memData2.isFunction = isFunc;
	
						//timeIsMoney("ReceiveMessage2-1:",timestart,14);
						//ハンドラが自分自身を呼び続けると Java のスタックが溢れてスクリプトスレッドごと死ぬので、
						//HyperCard と同様に "Too much recursion" のスクリプトエラーにする
						if(ScriptDebugger.frameDepth()>=MAX_HANDLER_DEPTH){
							throw new xTalkException("Too much handler recursion: {0} [{1}]", message, ScriptDebugger.frameTrail(6));
						}
						ScriptDebugger.Frame frame = ScriptDebugger.pushFrame(object, message, memData2, isFunc);
						//the handler's statements are expressions of their own, also when it was called from inside one (a user
						//function): their computed numbers are formatted and kept raw as at the top (put 2^h into v / return v
						//gave "16.0" in a function)
						int callerEvalDepth = evalDepth;
						evalDepth = 0;
						//the stack a passed message skips belongs to that message: the handler's own calls start their paths afresh
						//(三年日記: DiaryLib1's doOpenStack went on along the current card's path to DiaryLib3's makeDiary, whose
						//getToday() then missed DiaryLib2 — "gettodayがわかりません")
						OObject callerPathSkip = dynamicPathSkip;
						dynamicPathSkip = null;
						try {
							result = doScript(object,target,message,object.scriptList,start,line-1,memData2,params,0);
							//return 文で終わらなかったハンドラの値は空(HyperCard)。最後に実行した文の Result をそのまま返すと、
							//最後に呼んだ XCMD やハンドラの結果が関数の値になってしまうため、空に戻す
							if(result.ret!=3 && result.ret!=-1){ Result r = new Result(); r.ret = result.ret; r.theResult = ""; result = r; }
							//exit repeat/exit handler/return/next repeat によるハンドラ終了は
							//呼び出し側から見れば正常終了。ここで正規化しておかないと、
							//呼び出し元のif文やrepeat文が誤って中断されてしまう
							if(result.ret==2 || result.ret==3 || result.ret==4) result.ret=0;
						}
						catch (xTalkException err) {
							//エラーダイアログは既に出ている(または中断)。呼び出し元へ伝える
							result.ret = -1;
							break;
						}
						catch (Exception err) {
							if(object.name.length()>0)
								System.out.println(object.objectType+" '"+object.name+"' "+message+": "+err);
							else
								System.out.println(object.objectType+" id "+object.id+" "+message+": "+err);
							err.printStackTrace();
							result.ret = -1;
							break;
						}
						finally {
							evalDepth = callerEvalDepth;
							dynamicPathSkip = callerPathSkip;
							ScriptDebugger.popFrame(frame);
							if(ScriptDebugger.frameDepth()==0) exitingToHyperCard = false; //the handlers have ended
						}
						// The first matching end belongs to this handler. Continuing the scan
						// could incorrectly pair a stray or duplicate later `end <message>`
						// with the same start line and execute across intervening handlers.
						break;
					}
				}
				line++;
			}
		}
		
		//timeIsMoney("ReceiveMessage2-2:",timestart,15);
		if(result.ret==1){
			OCard curCard = (PCARD.pc!=null && PCARD.pc.stack!=null) ? PCARD.pc.stack.curCard : null;
			OPanel panel = object.parent instanceof OCardBase ? ((OCardBase)object.parent).panelOf(object) : null;
			if(object.parent==null && object instanceof OCard && object!=curCard){
				//a card that is not shown and whose background was never loaded: its message path still goes through that
				//background (HC J-2.3 probe C Quoted Cards: send "dataBgHandler" to card "28" reaches bkgnd "Data")
				OBackground bg = ((OCard)object).getBg();
				if(bg!=null) object.parent = bg;
			}
			if(panel!=null){
				//Panelに入っているボタン・フィールド・シェイプ: 部品 → Panel → カード(背景の部品もPanelの後で一度カードを通る)
				result=ReceiveMessage(message, params, panel, target, memData, result, isFunc, isDynamic, isBgroot, usingCnt);
			}
			else if(object.parent!=null){
				//通常パス:親に送信
				/*if(object.objectType.equals("background")&&isBgroot==false){
					//バックグラウンドは一度カードを通ってから
					System.out.println("!1");
					result=ReceiveMessage(message, params, ((OBackground)object).viewCard, target, isFunc, isDynamic, true);
				}
				else*/ if(object.parent.objectType.equals("background")&&!object.objectType.equals("card")){
					//バックグラウンドのパーツは一度カードを通ってから
					//(a background no longer shown has no card: its part goes on to it and its stack. ScenarioWriter's returnMenu
					//pops a card of another stack, then calls its own stack's unlockAllclose — it went to the current card instead)
					OCard viewCard = ((OBackground)object.parent).viewCard;
					result=ReceiveMessage(message, params, viewCard!=null ? viewCard : object.parent, target, memData, result, isFunc, isDynamic, isBgroot, usingCnt);
				}
				else{
					result=ReceiveMessage(message, params, object.parent, target/*object.parent*/, memData, result, isFunc, isDynamic, isBgroot, usingCnt);
				}
			}
			else if(MSG_PATH_TRACE && object instanceof OStack && debugOwnStack((OStack)object, message, isFunc)) {}
			else if(!isDynamic && usingCnt==0 && object instanceof OStack && PCARD.pc!=null && PCARD.pc.stack!=null && object!=PCARD.pc.stack
					&& !isCurrentStackInUse((OStack)object) && TXcmd.has68kExternal((OStack)object, message, isFunc ? "function" : "command")){
				//the running handler's own stack, outside the current card's hierarchy: HyperCard looks into its resource fork as the
				//message passes it, before going on with the current card's path. Dartmouth XCMD's ResInStack goes to the target
				//stack and calls its own IsResource XFCN there ("isresourceがわかりません")
				messageReachedSystem = true;
				result=TXcmd.CallExternalCommandOf((OStack)object, message, params, target, memData, isFunc, result);
			}
			else if(!isDynamic && target!=null && curCard!=null && (
					target.parent!=null && "background".equals(target.parent.objectType) && !"card".equals(target.objectType) ||
					"background".equals(target.objectType) && target != sentOnCard(curCard).bg ||
					"stack".equals(target.objectType) && target != PCARD.pc.stack ||
					"card".equals(target.objectType) && target != sentOnCard(curCard) ||
					startsOffCurrentCard(curCard))){
				//(a handler call starts at the handler's own object: ePhase's mouseUp goes to card shotMode, whose ShotIt goes back
				// to ePhase and calls eShot — only ePhase has it, and the target is ePhase again. HC reaches it through the
				// current card, FROMINE VR LIKA)
				//(カレントカードの階層にある this stack / this background へ send した分は、passされても
				// カレントカードへ戻さない。戻すと同じメッセージが無限再帰することがある)
				//ダイナミックパス:現在のカードに送信(カード自身が最初の受信者だった場合は、
				//スタックでpassされてもカレントカードへ送り直さない。以前はカードの親がbgなので
				//この条件に当てはまり、closeCard等がカードとスタックに二度届いていた)
				//ダイナミックパス:現在のカードに送信
				result=ReceiveMessage(message, params, curCard, target, memData, result, isFunc, true, isBgroot, usingCnt);
			}
			else if(!isDynamic && target!=null && curCard!=null && target.parent!=null &&
					"card".equals(target.parent.objectType) && target.parent != sentOnCard(curCard)){
				//ダイナミックパス:現在のカードに送信
				result=ReceiveMessage(message, params, curCard, target, memData, result, isFunc, true, isBgroot, usingCnt);
			}
			else if(!isDynamic && usingCnt==0 && object instanceof OStack && object!=PCARD.pc.stack && curCard!=null &&
					PCARD.pc.stack!=null && dynamicPathSkip==null && !isCurrentStackInUse((OStack)object)){
				//a handler of a stack outside the current card's hierarchy (a stack in use, sent to as "me") lets a message go:
				//HyperCard J-2.3 goes on with the current card's path (measured: a stack in use whose barT passes reaches the
				//current card's barT; 宇宙への旅's "pass music" reaches 音響ﾓｼﾞｭｰﾙ's on Music). That stack is not visited twice
				dynamicPathSkip = object;
				try{
					result=ReceiveMessage(message, params, curCard, target, memData, result, isFunc, true, isBgroot, 0);
				}finally{
					dynamicPathSkip = null;
				}
			}
			else {
				OObject owner = object;
				while(owner != null && !(owner instanceof OStack)) owner = owner.parent;
				OStack stack = (OStack)owner;
				//using スタック自身(usingCnt>0)から先は、それを使っているスタックの一覧の続きを辿る。以前は using スタック
				//自身の(空の)一覧を見ていたため、一覧の2番目以降(Home の後ろに積まれたライブラリ)へ届かなかった(DD の Uset)
				if(usingCnt>0 && object instanceof OStack){
					OStack current = PCARD.pc!=null ? PCARD.pc.stack : null;
					if(current!=null && current.usingStacks!=null && current.usingStacks.contains(object)) stack = current;
				}
				//a stack's own external comes right after its script, before the stacks in use and Home: WindowTalk's getHomeInfo
				//XCMD ran HyperZebra Home's getHomeInfo handler instead (HyperCard looks into each stack's resource fork as the
				//message passes it). Only when a handler further on would take the message first; otherwise the end of the path
				//below runs the external as before. One that passes goes on along the path
				if(object instanceof OStack && handlerFurtherOn(stack, usingCnt, message) &&
						TXcmd.has68kExternal((OStack)object, message, isFunc ? "function" : "command")){
					Result taken = TXcmd.CallExternalCommandOf((OStack)object, message, params, target, memData, isFunc, result);
					if(taken.ret==0) return taken;
					result = taken;
					result.ret = 1;
				}
				//スクリプトを読めていない(空の)using スタックは飛ばして次を見る
				//今のスタック自身が使用中の一覧にあれば(start using this stack の後で戻ってきた)二度目は届けない
				while(stack!=null && stack.usingStacks!=null && usingCnt < stack.usingStacks.size() &&
						(stack.usingStacks.get(usingCnt)==null || stack.usingStacks.get(usingCnt).scriptList==null ||
						 isCurrentStackInUse(stack.usingStacks.get(usingCnt)) || stack.usingStacks.get(usingCnt)==dynamicPathSkip)) usingCnt++;
				if(stack!=null && stack.usingStacks!=null && usingCnt < stack.usingStacks.size() &&
						stack.usingStacks.get(usingCnt)!=null && stack.usingStacks.get(usingCnt).scriptList!=null){
					usingCnt++;
					result=ReceiveMessage(message, params, stack.usingStacks.get(usingCnt-1), target, memData, result, isFunc, true, isBgroot, usingCnt);
				}
				else if(!commandSet.contains(message) || (!isFunc && TXcmd.runnable68kExternal(message, "command")) ||
						(isFunc && TXcmd.externalOwner(message, "function")!=null)){ //an XFCN named like a command (バーチャマック's Drag(…))
					messageReachedSystem = true; //どのハンドラにも捕まえられずにHyperCard自身へ届いた(組み込みコマンドと同名の XCMD もここで動く)
					result=TUtil.CallSystemMessage(message, params, target, memData, isFunc);
				}
			}
		}

		return result;//0なら見つかった、1なら見つからなかったので次のオブジェクトを探す
	}
	

	/** A stack in use from {@code from} on (Home included) has a handler for {@code message} */
	private static boolean handlerFurtherOn(OStack stack, int from, String message){
		if(stack==null || stack.usingStacks==null) return false;
		String m = message.toLowerCase();
		for(int i=Math.max(0, from); i<stack.usingStacks.size(); i++){
			OStack u = stack.usingStacks.get(i);
			if(u==null || u.scriptList==null || isCurrentStackInUse(u)) continue;
			ensureHandlerList(u);
			if(u.handlerList!=null && u.handlerList.contains(m)) return true;
		}
		return false;
	}

	/** Whether the message started on a card or background that is not the current card's (not a stack: those keep their own rules) */
	private boolean startsOffCurrentCard(OCard curCard){
		return messagePathStartOff;
	}
	private static boolean debugOwnStack(OStack st, String message, boolean isFunc){
		Rsrc r = TXcmd.resourcesOf(st);
		System.err.println("[path] own stack "+st.getShortName()+" rsrc="+(st.rsrc!=null)+" closed="+(st.closedResources!=null)+" has="+TXcmd.has68kExternal(st, message, isFunc ? "function" : "command")+" xcmds="+(r==null?"-":r.getXcmdResources().size())+" inUse="+isCurrentStackInUse(st)+" cur="+(PCARD.pc.stack==st));
		return false;
	}
	/** The card that was current when the message being passed was sent (curCard for a path entered another way) */
	private OCard sentOnCard(OCard curCard){
		return messageSendCard!=null ? messageSendCard : curCard;
	}
	/** Whether a message starting at {@code start} (a card, background or part; not a stack) is off {@code curCard}'s hierarchy */
	private static boolean startsOff(OObject start, OCard curCard){
		if(start==null || start instanceof OStack) return false;
		if(start instanceof OCard) return start != curCard;
		if(start instanceof OBackground) return start != curCard.bg;
		OObject owner = start.parent instanceof OCardBase ? start.parent : null;
		if(owner instanceof OCard) return owner != curCard;
		if(owner instanceof OBackground) return owner != curCard.bg;
		return false;
	}

	/** The name expression after an object word ("stack value of word 2 of long name of this stack", Rinaldi's X-Archive):
	 *  the words there were typed as the object's name, so a function at its start is read again as an expression. */
	private static String evalAfterObjectWord(ArrayList<String> stringList, wordType[] typeAry, int from, int to,
			MemoryData memData, OObject object, OObject target) throws xTalkException
	{
		if(from+1<=to && typeAry[from]==wordType.X && typeAry[from+1]==wordType.OF_OBJ && funcSet.contains(stringList.get(from).toLowerCase())){
			StringBuilder text = new StringBuilder();
			for(int i=from; i<=to; i++){
				if(text.length()>0) text.append(' ');
				text.append(typeAry[i]==wordType.STRING ? quoteLiteral(stringList.get(i)) : stringList.get(i));
			}
			return Evalution(text.toString(), memData, object, target);
		}
		return Evalution(stringList, typeAry, from, to, memData, object, target);
	}

	/** A bare object name that would end the object in the rebuilt "set visible of … to true" of show: Logo 2.1's
	 *  "show field TO" (HyperCard shows the field named TO) */
	/** A number written without quotes (card 1, window 8): rebuilt into a line it stays a number, not a quoted name ("show window
	 *  8" became set visible of window "8", the window named 8: JHUG Libra Demo) */
	private static boolean bareNumberToken(String word){
		return isOrdinalNumber(word) && !isQuotedNumberLiteral(word);
	}

	private static boolean rebuiltNeedsQuotes(String word){
		return word.equalsIgnoreCase("to");
	}

	//mode=0 通常    mode=1 内部呼び出しなのでエラー出さない 
	private Result doScript(OObject object, OObject target, String message, String script, MemoryData memData, String[] parentparams,int mode)
	throws xTalkException
	{
		ArrayList<String> scriptList = scriptLines(script);
		return doScript(object,target,message,scriptList,0,scriptList.size()-1,memData,parentparams,mode);
	}

	//文字列のスクリプトを実行する行のリストにする(CRはLFとみなし、継続行を連結する)
	static ArrayList<String> scriptLines(String script) {
		ArrayList<String> scriptList = new ArrayList<String>();
		script = script.replace('\r', '\n'); //return(CR)を(LF)に変える
		String[] scrAry = script.split("\n");
		
		for(int i=0; i<scrAry.length; i++){
			scriptList.add(scrAry[i]);
		}
		joinContinuationLines(scriptList);
		return scriptList;
	}

	//行末の継続記号(¬)で終わる行を次の行と結合する。
	//行番号(スクリプトエディタでのエラー表示やハンドラ行の位置)を保つため、
	//結合した行を後ろの行に置き、前の行は空行にする。
	//'ﾂ'はMacJapaneseデコードで¬が化けたもの、'~'はHyperZebra独自の代替記号。
	static boolean isContinuationChar(char c) {
		return c=='¬' || c=='ﾂ' || c=='~';
	}

	/**
	 * The script as "the script" returns it. HyperCard keeps scripts without indentation and lays them out when they are
	 * read: two spaces per level inside on/function, repeat and if…then blocks, else at its if's level (HyperCard J-2.3:
	 * "on mouseUp<CR>  beep<CR>  if 1 then<CR>    beep<CR>  end if<CR>end mouseUp" for a script set without
	 * indentation). Leading spaces/tabs are replaced, everything else is kept as it is.
	 */
	static String formatScript(java.util.List<String> lines) {
		StringBuilder out = new StringBuilder();
		ArrayList<String> blocks = new ArrayList<String>(); //"on" / "repeat" / "if"
		boolean afterSingleIf = false; //the previous line was "if … then <statement>": an "else" line belongs to it
		boolean continued = false;
		for(int n=0; n<lines.size(); n++){
			String raw = lines.get(n);
			int k = 0;
			while(k<raw.length() && (raw.charAt(k)==' ' || raw.charAt(k)=='\t')) k++;
			//行末の空白も除く(HyperCard J-2.3: "    beep   " → "  beep")
			String text = raw.substring(k).stripTrailing();
			if(n>0) out.append('\n');
			if(text.isEmpty()){ continue; }
			if(continued){
				//継続行(¬)は前の行と同じ深さ(HyperCard J-2.3)。ブロックの判定には使わない
				for(int j=0; j<blocks.size(); j++) out.append("  ");
				out.append(text);
				continued = endsWithContinuation(text);
				continue;
			}
			String code = withoutComment(text);
			String[] words = code.trim().isEmpty() ? new String[0] : code.trim().toLowerCase(Locale.ROOT).split("[ \t]+");
			String first = words.length>0 ? words[0] : "";
			String last = words.length>0 ? words[words.length-1] : "";
			int level = blocks.size();
			if(first.equals("end") && !blocks.isEmpty()){
				String what = words.length>1 ? words[1] : "";
				String top = blocks.get(blocks.size()-1);
				if(what.equals("repeat") ? top.equals("repeat") : what.equals("if") ? top.equals("if") : top.equals("on")){
					blocks.remove(blocks.size()-1);
				}
				level = blocks.size();
			}
			else if(first.equals("else")){
				if(!afterSingleIf && !blocks.isEmpty() && blocks.get(blocks.size()-1).equals("if")) level = blocks.size()-1;
			}
			for(int j=0; j<level; j++) out.append("  ");
			out.append(text);
			boolean singleIf = false;
			if(words.length==0){
				//注釈だけの行
			}
			else if((first.equals("on") || first.equals("function")) && words.length>=2 && blocks.isEmpty()){
				blocks.add("on");
			}
			else if(first.equals("repeat") && !blocks.isEmpty()){
				blocks.add("repeat");
			}
			else if(first.equals("if")){
				//"if … then 文 else" ⏎ 文… ⏎ end if: 行末の else から本体が続く
				if(last.equals("then") || (last.equals("else") && java.util.Arrays.asList(words).contains("then"))) blocks.add("if");
				else singleIf = words.length>1 && java.util.Arrays.asList(words).contains("then");
			}
			else if(first.equals("else")){
				boolean inBlock = !afterSingleIf && !blocks.isEmpty() && blocks.get(blocks.size()-1).equals("if");
				if(words.length==1 || last.equals("then") || last.equals("else")){
					//else だけ、または else if … then: ブロックが続く(片行の if の後なら新しいブロック)
					if(!inBlock) blocks.add("if");
				}
				else{
					//else <文>: ブロックはここで終わる。else if … then <文> なら次の else もそれに付く
					if(inBlock) blocks.remove(blocks.size()-1);
					singleIf = words.length>1 && words[1].equals("if");
				}
			}
			afterSingleIf = singleIf;
			continued = endsWithContinuation(text);
		}
		return out.toString();
	}

	/** The line without its "--" comment (a "--" inside quotes is text). */
	private static String withoutComment(String line) {
		boolean quoted = false;
		for(int i=0; i+1<line.length(); i++){
			char c = line.charAt(i);
			if(c=='"') quoted = !quoted;
			else if(!quoted && c=='-' && line.charAt(i+1)=='-') return line.substring(0, i);
		}
		return line;
	}

	private static boolean endsWithContinuation(String text) {
		String t = withoutComment(text).stripTrailing();
		return !t.isEmpty() && isContinuationChar(t.charAt(t.length()-1));
	}

	static void joinContinuationLines(ArrayList<String> scriptList) {
		for(int i=0; i<scriptList.size(); i++){
			String str=scriptList.get(i);
			//"¬ -- comment": a comment after the continuation character still continues the line (HyperCard 2.4
			//Readymade Fields "Display the card number", Power Tools "Show Palette...")
			while(i+1<scriptList.size() && str.length()>0 &&
					(endsWithContinuation(str) || dictionaryBraceDepth(str)>0))
			{
				boolean explicit = endsWithContinuation(str);
				i++;
				if(explicit){ String code = withoutComment(str).stripTrailing(); str = code.substring(0, code.length()-1); }
				str = str+" "+scriptList.get(i);
				scriptList.set(i-1, "");
				scriptList.set(i, str);
			}
		}
	}

	private static int dictionaryBraceDepth(String script) {
		int depth=0;
		boolean quoted=false;
		for(int i=0; i<script.length(); i++){
			char c=script.charAt(i);
			if(c=='"') quoted=!quoted;
			else if(!quoted && c=='{') depth++;
			else if(!quoted && c=='}') depth--;
		}
		return depth;
	}
	
	

	private static void tokenizeControlLine(String line, ArrayList<String> strings, ArrayList<wordType> types) {
		resolution(line, strings, types, false);
	}

	private static int findToken(ArrayList<String> strings, int start, String token) {
		for(int i=start; i<strings.size(); i++) {
			if(strings.get(i).equalsIgnoreCase(token)) return i;
		}
		return -1;
	}

	/** The keyword {@code token} from start: a quoted "then"/"else"/"if"/"end" is text, not the keyword (if x is "then" then …
	 *  was "Invalid comparison operator", put "else" into r in a then branch split the line there) */
	private static int findToken(ArrayList<String> strings, ArrayList<wordType> types, int start, String token) {
		for(int i=start; i<strings.size(); i++) {
			if(isKeywordAt(strings, types, i, token)) return i;
		}
		return -1;
	}

	/** strings[i] is the keyword {@code word}, not a quoted text that reads the same */
	private static boolean isKeywordAt(ArrayList<String> strings, ArrayList<wordType> types, int i, String word) {
		return i>=0 && i<strings.size() && (types==null || i>=types.size() || types.get(i)!=wordType.STRING) && strings.get(i).equalsIgnoreCase(word);
	}

	private static boolean isEndIfLine(ArrayList<String> strings) {
		return strings.size() >= 2 && strings.get(0).equalsIgnoreCase("end") && strings.get(1).equalsIgnoreCase("if");
	}

	/** A statement that ends with else inside a multi-line if: "if c then" ⏎ "put 0 into n else" ⏎ … ⏎ "end if" - the
	 *  statement is the last of the then branch and the else branch starts on the next line (HC J-2.3 probe Umich
	 *  Trailing Else; umich RefStack 1.5.1) */
	private static boolean trailingElseLine(ArrayList<String> strings, ArrayList<wordType> types) {
		int n = strings.size();
		if(n<2 || types.get(n-1)==wordType.STRING || !strings.get(n-1).equalsIgnoreCase("else")) return false;
		String first = strings.get(0).toLowerCase(Locale.ROOT);
		if(first.equals("if") || first.equals("else") || first.equals("then") || first.equals("end") || first.startsWith("--")) return false;
		return findToken(strings, types, 0, "then")<0;
	}

	private static boolean isElseLine(ArrayList<String> strings) {
		return !strings.isEmpty() && strings.get(0).equalsIgnoreCase("else");
	}

	private static final class IfBranch {
		String condition;       // nullならelse節
		int bodyStart = -1;
		int bodyEnd = -1;
		String inlineScript;
		IfStructure nested;     // "if A then if B then"のように、then節が次行以降に続く多行ifのとき
		private ArrayList<String> inlineLines;

		//1行節の文を実行する行のリスト。構造はキャッシュされるので、実行のたびに分割しないよう同じリストを使う
		ArrayList<String> inlineLines() {
			ArrayList<String> lines = inlineLines;
			if(lines==null) inlineLines = lines = scriptLines(inlineScript);
			return lines;
		}
	}

	//if文全体の構造。branchesは先頭から順に評価し、最初に成立した節だけ実行する。
	//endLineは構造の最終行(end if行、または構造を閉じる1行else/then行)。
	private static final class IfStructure {
		ArrayList<IfBranch> branches = new ArrayList<IfBranch>();
		int endLine;
	}

	//"if 条件 then [文]" / "else if 条件 then [文]"の見出し。thenは次行に置かれることもある。
	private static final class IfHeader {
		String condition;
		ArrayList<String> strings;  // thenがある行のトークン
		ArrayList<wordType> types;
		int thenIndex = -1;
		int thenLine;               // thenがある行
		boolean multiline;          // thenの後ろに文がない
	}

	private static IfHeader parseIfHeader(ArrayList<String> scriptList, int line, int end,
			ArrayList<String> strings, ArrayList<wordType> types, int conditionStart) throws xTalkException {
		IfHeader header = new IfHeader();
		header.strings = strings;
		header.types = types;
		header.thenLine = line;
		header.thenIndex = findToken(strings, types, conditionStart, "then");

		if(header.thenIndex >= 0) {
			header.condition = combine(conditionStart, header.thenIndex, strings, types);
			header.multiline = header.thenIndex == strings.size()-1;
			return header;
		}

		// HyperTalkではthenを次の行に置く書き方も許容する(間の空行・コメント行は読み飛ばす: Clipboard スタックの
		// "else if ClipInfo(…) = """ / 空行 / "then answer …")
		int next = line + 1;
		ArrayList<String> nextStrings = new ArrayList<String>();
		ArrayList<wordType> nextTypes = new ArrayList<wordType>();
		while(next <= end) {
			nextStrings.clear();
			nextTypes.clear();
			tokenizeControlLine(scriptList.get(next), nextStrings, nextTypes);
			if(!nextStrings.isEmpty()) break;
			next++;
		}
		if(next <= end) {
			if(isKeywordAt(nextStrings, nextTypes, 0, "then")) {
				header.condition = combine(conditionStart, strings.size(), strings, types);
				header.thenLine = next;
				header.strings = nextStrings;
				header.types = nextTypes;
				header.thenIndex = 0;
				header.multiline = nextStrings.size() == 1;
				return header;
			}
		}
		throw new xTalkException("An if statement requires then");
	}

	private static int findOuterInlineElse(ArrayList<String> strings, ArrayList<wordType> types, int start) {
		int nestedInlineIf = 0;
		for(int i=start; i<strings.size(); i++) {
			if(isKeywordAt(strings, types, i, "if")) {
				nestedInlineIf++;
			}
			else if(isKeywordAt(strings, types, i, "else")) {
				if(nestedInlineIf > 0) nestedInlineIf--;
				else return i;
			}
		}
		return -1;
	}

	//空行とコメント行を飛ばして次の行番号を返す。無ければend+1。
	private static int nextControlLine(ArrayList<String> scriptList, int line, int end) {
		while(line <= end) {
			ArrayList<String> words = new ArrayList<String>();
			ArrayList<wordType> types = new ArrayList<wordType>();
			tokenizeControlLine(scriptList.get(line), words, types);
			if(!words.isEmpty() && !words.get(0).startsWith("--")) return line;
			line++;
		}
		return end+1;
	}

	/** "then repeat …" whose repeat is not closed on the same line: the line of its matching end repeat, or -1 */
	private static int thenRepeatEnd(ArrayList<String> scriptList, IfHeader header, int end) {
		return openRepeatEnd(scriptList, header.strings, header.types, header.thenIndex+1, header.thenLine, end);
	}

	/** The statement strings[from…] on the line {@code line} is a repeat that is not closed on that line ("then repeat …",
	 *  "else repeat …"): the line of its matching end repeat, or -1 */
	private static int openRepeatEnd(ArrayList<String> scriptList, ArrayList<String> strings, ArrayList<wordType> stringTypes, int from, int line, int end) {
		if(!isKeywordAt(strings, stringTypes, from, "repeat")) return -1;
		if(findToken(strings, stringTypes, from, "end")>=0 || findToken(strings, stringTypes, from, "else")>=0) return -1;
		int depth = 0;
		for(line=line+1; line<=end; line++){
			ArrayList<String> words = new ArrayList<String>();
			ArrayList<wordType> types = new ArrayList<wordType>();
			tokenizeControlLine(scriptList.get(line), words, types);
			if(words.isEmpty()) continue;
			if(words.get(0).equalsIgnoreCase("repeat")) depth++;
			else if(words.size()>=2 && words.get(0).equalsIgnoreCase("end") && words.get(1).equalsIgnoreCase("repeat")){
				if(depth==0) return line;
				depth--;
			}
			else if(words.get(0).equalsIgnoreCase("end") && depth==0 &&
					!(words.size()>=2 && words.get(1).equalsIgnoreCase("if"))) return -1; //end of the handler first (end if of an if inside)
		}
		return -1;
	}

	/** The "else 文" line {@code line} as the last branch of the structure. "else repeat …" whose repeat goes on to the
	 *  following lines runs up to its end repeat, without end if (HyperCard: Free Fighters -NEXT-'s
	 *  "if MH > 258 then repeat … ⏎ end repeat ⏎ else repeat with i=4 to 6 ⏎ … ⏎ end repeat") */
	private static void addInlineElse(IfStructure structure, ArrayList<String> scriptList, int line, int end,
			ArrayList<String> words, ArrayList<wordType> wordTypes) {
		IfBranch branch = new IfBranch();
		branch.condition = null;
		branch.inlineScript = combine(1, words.size(), words, wordTypes);
		structure.endLine = line;
		int repeatEnd = openRepeatEnd(scriptList, words, wordTypes, 1, line, end);
		if(repeatEnd >= 0) {
			StringBuilder body = new StringBuilder(branch.inlineScript);
			for(int k=line+1; k<=repeatEnd; k++) body.append('\n').append(scriptList.get(k));
			branch.inlineScript = body.toString();
			structure.endLine = repeatEnd;
		}
		structure.branches.add(branch);
	}

	//"then 文 [else 文]"の形の1行節をbranchesへ追加する。else側があれば無条件節として続ける。
	//外側のelseだけを探し、then節中のネストした1行ifのelseはそのifに結び付ける。
	//行末が "else if 条件 then" で終わるときはその if の位置を返す(節は加えない): その本体は次の行からの
	//多行の節で、end if で閉じる(HyperCard J-2.3/2.4 で確認。HamStar 1.1 の "if it is "キャンセル" then exit mouseup
	//else if it is "保存" then" ⏎ 文 ⏎ end if)。それ以外は -1。
	private static int addInlineBranches(ArrayList<IfBranch> branches, String condition,
			ArrayList<String> strings, ArrayList<wordType> types, int thenIndex) {
		IfBranch branch = new IfBranch();
		branch.condition = condition;
		int elseIndex = findOuterInlineElse(strings, types, thenIndex+1);
		int thenEnd = elseIndex >= 0 ? elseIndex : strings.size();
		branch.inlineScript = combine(thenIndex+1, thenEnd, strings, types);
		branches.add(branch);
		if(elseIndex >= 0 && isKeywordAt(strings, types, elseIndex+1, "if")) {
			//"else if 条件 then 文 …" が同じ行に続く: 連鎖の節として展開する。行末の else の次行以降の本体と
			//次の行の else が、連鎖の最後の if に付くようにするため(串「ゲーム開始」の
			//"if … then next repeat else if … then … else if … then … else" ⏎ 文… ⏎ end if)
			int innerThen = findToken(strings, types, elseIndex+2, "then");
			if(innerThen > elseIndex+2 && innerThen < strings.size()-1) {
				return addInlineBranches(branches, combine(elseIndex+2, innerThen, strings, types), strings, types, innerThen);
			}
			if(innerThen > elseIndex+2 && innerThen == strings.size()-1) return elseIndex+1;
			//"… else if 条件" ⏎ "then 文": その if の then は次の行(HyperCard J-2.3、probe B17 Else If Then Line。Dumbit
			//Sound.1 の "if it=545 then put len into offset else if lft≠mv" ⏎ "then put trunc(…) into offset")
			if(innerThen < 0 && elseIndex+2 < strings.size()) return elseIndex+1;
		}
		if(elseIndex >= 0) {
			IfBranch elseBranch = new IfBranch();
			elseBranch.condition = null;
			elseBranch.inlineScript = combine(elseIndex+1, strings.size(), strings, types);
			branches.add(elseBranch);
		}
		return -1;
	}

	//"if A then if B then"のように、then節が多行ifの見出しだけで終わっている場合、
	//その多行ifの本体は次行以降に続き、end ifで閉じる(HyperCardの解釈)。
	//該当すれば見出し行の残りから読んだ内側の構造を返し、そうでなければnull。
	private static IfStructure parseNestedInlineIf(ArrayList<String> scriptList, IfHeader header, int end)
			throws xTalkException {
		ArrayList<String> strings = header.strings;
		int from = header.thenIndex + 1;
		if(strings.size() - from < 2) return null;
		if(!isKeywordAt(strings, header.types, from, "if")) return null;
		boolean thenAtEnd = strings.size() - from >= 3 && isKeywordAt(strings, header.types, strings.size()-1, "then");
		//"if A then if B" ⏎ "then 文": 内側の if の then が次の行にある(Fixed QuickTimeTools)
		boolean thenOnNextLine = false;
		if(!thenAtEnd && findToken(strings, header.types, from+1, "then") < 0 && header.thenLine+1 <= end){
			ArrayList<String> nextWords = new ArrayList<String>();
			ArrayList<wordType> nextTypes = new ArrayList<wordType>();
			tokenizeControlLine(scriptList.get(header.thenLine+1), nextWords, nextTypes);
			thenOnNextLine = !nextWords.isEmpty() && nextWords.get(0).equalsIgnoreCase("then");
		}
		if(!thenAtEnd && !thenOnNextLine) return null;
		ArrayList<String> nestedStrings = new ArrayList<String>(strings.subList(from, strings.size()));
		ArrayList<wordType> nestedTypes = new ArrayList<wordType>(header.types.subList(from, header.types.size()));
		return parseIfStructure(scriptList, header.thenLine, end, nestedStrings, nestedTypes);
	}

	//if文の構造を読み取る。HyperTalkのif文は次の形をすべて受け付ける。
	//  if 条件 then 文 [else 文]                     -- 1行で完結
	//  if 条件 then if 条件 then / 文... / end if    -- then節が多行ifの見出しで、本体は次行以降
	//  if 条件 then 文 / else 文                     -- 次行のelseで閉じる
	//  if 条件 then 文 / else / 文... / end if
	//  if 条件 then / 文... / else 文               -- 1行elseは end if なしで閉じる
	//  if 条件 then / 文... / else if 条件 then ... / else / 文... / end if
	//  if 条件 / then ...                            -- thenを次行に置く
	//ネストしたif文は再帰的に読み飛ばすので、実行されない節の中にある
	//else/end ifが外側の構造と混同されることはない。
	private static IfStructure parseIfStructure(ArrayList<String> scriptList, int line, int end,
			ArrayList<String> strings, ArrayList<wordType> types) throws xTalkException {
		IfStructure structure = new IfStructure();
		IfHeader header = parseIfHeader(scriptList, line, end, strings, types, 1);
		int scan = line;
		while(true) {
			// header: if/else ifの見出し(thenを含む)
			if(!header.multiline) {
				IfStructure nested = parseNestedInlineIf(scriptList, header, end);
				if(nested != null) {
					// 内側のend ifでこのif文全体が閉じる。続くelseは外側のif文のもの。
					IfBranch branch = new IfBranch();
					branch.condition = header.condition;
					branch.nested = nested;
					structure.branches.add(branch);
					structure.endLine = nested.endLine;
					return structure;
				}
				int repeatEnd = thenRepeatEnd(scriptList, header, end);
				if(repeatEnd >= 0) {
					//"if 条件 ⏎ then repeat … ⏎ … ⏎ end repeat": then の文は end repeat までの repeat 構造で、end if は要らない
					//(HyperCard J-2.3 で確認。Rites of Passage の Contents 1)
					IfBranch branch = new IfBranch();
					branch.condition = header.condition;
					StringBuilder body = new StringBuilder(combine(header.thenIndex+1, header.strings.size(), header.strings, header.types));
					for(int k=header.thenLine+1; k<=repeatEnd; k++) body.append('\n').append(scriptList.get(k));
					branch.inlineScript = body.toString();
					structure.branches.add(branch);
					structure.endLine = repeatEnd;
				}
				else {
					int openIf = addInlineBranches(structure.branches, header.condition, header.strings, header.types, header.thenIndex);
					structure.endLine = header.thenLine;
					if(openIf >= 0) {
						//"… else if 条件 then" で終わる行: その else if は次の行からの多行の節(addInlineBranches)
						header = parseIfHeader(scriptList, header.thenLine, end, header.strings, header.types, openIf+1);
						continue;
					}
					IfBranch last = structure.branches.get(structure.branches.size()-1);
					if(last.condition == null && isKeywordAt(header.strings, header.types, header.strings.size()-1, "else") &&
							(last.inlineScript==null || last.inlineScript.trim().isEmpty())) {
						//"if 条件 then 文 else" ⏎ 文… ⏎ end if: 行末の else から次の行以降が else 節(HyperCard J-2.3 で確認。
						//HyperGobbledygook の togMB)
						last.inlineScript = null;
						last.bodyStart = header.thenLine + 1;
						int close = findBlockEnd(scriptList, last.bodyStart, end);
						last.bodyEnd = close - 1;
						ArrayList<String> closeWords = new ArrayList<String>();
						ArrayList<wordType> closeTypes = new ArrayList<wordType>();
						tokenizeControlLine(scriptList.get(close), closeWords, closeTypes);
						if(!isEndIfLine(closeWords)) throw new xTalkException("Cannot find end if");
						structure.endLine = close;
						return structure;
					}
					// "then 文 else 文"で1行に閉じていれば終わり
					if(last.condition == null) return structure;
				}
				// 次の行がelseならこのif文の続き。そうでなければここで閉じる。
				int next = nextControlLine(scriptList, structure.endLine+1, end);
				if(next > end) return structure;
				ArrayList<String> words = new ArrayList<String>();
				ArrayList<wordType> wordTypes = new ArrayList<wordType>();
				tokenizeControlLine(scriptList.get(next), words, wordTypes);
				if(!isElseLine(words)) return structure;
				scan = next;
			}
			else {
				IfBranch branch = new IfBranch();
				branch.condition = header.condition;
				branch.bodyStart = header.thenLine + 1;
				structure.branches.add(branch);
				scan = findBlockEnd(scriptList, branch.bodyStart, end);
				branch.bodyEnd = scan - 1;
			}

			// scan: 深さ0のelse / else if / end if の行
			ArrayList<String> words = new ArrayList<String>();
			ArrayList<wordType> wordTypes = new ArrayList<wordType>();
			tokenizeControlLine(scriptList.get(scan), words, wordTypes);
			boolean statementElse = trailingElseLine(words, wordTypes);
			if(statementElse){
				//"put 0 into n else": the statement is the branch's last, an else block follows
				structure.branches.get(structure.branches.size()-1).bodyEnd = scan;
			}
			if(isEndIfLine(words)) {
				structure.endLine = scan;
				return structure;
			}
			if(words.size() >= 2 && isKeywordAt(words, wordTypes, 1, "if")) {
				header = parseIfHeader(scriptList, scan, end, words, wordTypes, 2);
				continue;
			}
			// else [文]
			if(words.size() > 1 && !statementElse) {
				addInlineElse(structure, scriptList, scan, end, words, wordTypes);
				return structure;
			}
			IfBranch branch = new IfBranch();
			branch.condition = null;
			branch.bodyStart = scan + 1;
			structure.branches.add(branch);
			scan = findBlockEnd(scriptList, branch.bodyStart, end);
			branch.bodyEnd = scan - 1;
			words = new ArrayList<String>();
			wordTypes = new ArrayList<wordType>();
			tokenizeControlLine(scriptList.get(scan), words, wordTypes);
			if(isEndIfLine(words)) {
				structure.endLine = scan;
				return structure;
			}
			// elseの後にさらにelse/else ifが続くのは本来誤りだが、寛容に同じ連鎖として扱う
			if(words.size() >= 2 && isKeywordAt(words, wordTypes, 1, "if")) {
				header = parseIfHeader(scriptList, scan, end, words, wordTypes, 2);
				continue;
			}
			if(words.size() > 1) {
				addInlineElse(structure, scriptList, scan, end, words, wordTypes);
				return structure;
			}
			throw new xTalkException("Cannot find end if");
		}
	}

	/**
	 * エディタの静的解析用。条件式を評価せず、if構造だけを実行時と同じ規則で解析し、
	 * その構造の最終行を返す。構文が不完全ならxTalkException。
	 */
	static int validateIfStructure(ArrayList<String> scriptList, int line, int end) throws xTalkException {
		if(scriptList==null || line<0 || line> end || end>=scriptList.size()) return line;
		ArrayList<String> words = new ArrayList<String>();
		ArrayList<wordType> types = new ArrayList<wordType>();
		tokenizeControlLine(scriptList.get(line), words, types);
		if(words.isEmpty() || !words.get(0).equalsIgnoreCase("if")) return line;
		return parseIfStructure(scriptList, line, end, words, types).endLine;
	}

	//bodyStartから始まる節の本体を読み、同じ深さのelse / else if / end ifの行番号を返す。
	//本体中のネストしたif文はparseIfStructureで丸ごと読み飛ばす。
	private static int findBlockEnd(ArrayList<String> scriptList, int bodyStart, int end) throws xTalkException {
		int scan = bodyStart;
		while(scan <= end) {
			ArrayList<String> words = new ArrayList<String>();
			ArrayList<wordType> wordTypes = new ArrayList<wordType>();
			tokenizeControlLine(scriptList.get(scan), words, wordTypes);
			if(words.isEmpty() || words.get(0).startsWith("--")) {
				scan++;
				continue;
			}
			if(isEndIfLine(words) || isElseLine(words) || trailingElseLine(words, wordTypes)) return scan;
			if(words.get(0).equalsIgnoreCase("if")) {
				scan = parseIfStructure(scriptList, scan, end, words, wordTypes).endLine + 1;
				continue;
			}
			scan++;
		}
		throw new xTalkException("Cannot find end if");
	}

	/** OObject.controlCache の項目。行 line から lines.length 行の String が解析したときと同一(==)で、
	 *  同じ範囲(end)の中で実行するときだけ value を使う。スクリプトが書き換われば行の String が変わるので外れる */
	static final class ControlCacheEntry {
		final int end;
		final String[] lines;
		final Object value;

		ControlCacheEntry(ArrayList<String> scriptList, int line, int lastLine, int end, Object value) {
			this.end = end;
			this.lines = scriptList.subList(line, lastLine+1).toArray(new String[0]);
			this.value = value;
		}

		boolean matches(ArrayList<String> scriptList, int line, int end) {
			if(this.end != end || line + lines.length > scriptList.size()) return false;
			for(int i=0; i<lines.length; i++){
				if(scriptList.get(line+i) != lines[i]) return false;
			}
			return true;
		}
	}

	/** オブジェクト自身のスクリプトを実行しているときだけ、その行の構造キャッシュを返す(無ければnull) */
	private static ControlCacheEntry controlCacheEntry(OObject object, ArrayList<String> scriptList, int key, int line, int end) {
		if(object==null || object.scriptList!=scriptList) return null;
		java.util.concurrent.ConcurrentHashMap<Integer,Object> cache = object.controlCache;
		if(cache==null) return null;
		Object entry = cache.get(key);
		if(entry instanceof ControlCacheEntry e && e.matches(scriptList, line, end)) return e;
		return null;
	}

	private static void putControlCache(OObject object, ArrayList<String> scriptList, int key, ControlCacheEntry entry) {
		if(object==null || object.scriptList!=scriptList) return;
		java.util.concurrent.ConcurrentHashMap<Integer,Object> cache = object.controlCache;
		if(cache==null) object.controlCache = cache = new java.util.concurrent.ConcurrentHashMap<Integer,Object>();
		cache.put(key, entry);
	}

	//if文の構造は行が変わらない限り同じなので、オブジェクトのスクリプトでは解析結果を使い回す
	private static IfStructure cachedIfStructure(OObject object, ArrayList<String> scriptList, int line, int end,
			ArrayList<String> sList, ArrayList<wordType> tList) throws xTalkException {
		ControlCacheEntry cached = controlCacheEntry(object, scriptList, line, line, end);
		if(cached!=null && cached.value instanceof IfStructure structure) return structure;
		IfStructure structure = parseIfStructure(scriptList, line, end, sList, tList);
		//解析は、1行で閉じたif文の後ろにelseが続くかを見るために次の(空行・コメントでない)行まで読む
		int lastLine = structure.endLine;
		int next = nextControlLine(scriptList, lastLine+1, end);
		if(next<=end) lastLine = next;
		putControlCache(object, scriptList, line, new ControlCacheEntry(scriptList, line, lastLine, end, structure));
		return structure;
	}

	//repeat の行 line に対応する end repeat の行を返す(オブジェクトのスクリプトでは結果を使い回す)
	private static int findEndRepeat(OObject object, ArrayList<String> scriptList, int line, int end) throws xTalkException {
		ControlCacheEntry cached = controlCacheEntry(object, scriptList, line, line, end);
		if(cached!=null && cached.value instanceof Integer endRepeat) return endRepeat;
		int start=line;
		line++;
		int nest=0;
		while(line<=end){
			//END REPEAT---------END CLEAR FIELD (AOL Cheese.Cake): a comment glued to the words is not part of them
			String str2=withoutComment(scriptList.get(line));
			String[] words2 = splitScriptWords(str2);
			if(words2.length==0) {line++; continue;}
			if(words2[0].equalsIgnoreCase("repeat")) {
				nest++;
			}
			else{
				//if it is "BBB-56" then repeat 1 … end repeat (AOL States\Continents; HC J-2.3 probe Aol If Then Repeat): a repeat
				//opened after then/else is a block of its own
				for(int k=0; k+1<words2.length; k++){
					if((words2[k].equalsIgnoreCase("then") || words2[k].equalsIgnoreCase("else")) && words2[k+1].equalsIgnoreCase("repeat")){ nest++; break; }
				}
			}
			if(words2.length>1 && words2[0].equalsIgnoreCase("end")&&words2[1].equalsIgnoreCase("repeat")) {
				if(nest==0) break;
				nest--;
			}
			line++;
		}
		if(line>end) throw new xTalkException("Cannot find end repeat");
		putControlCache(object, scriptList, start, new ControlCacheEntry(scriptList, start, line, end, Integer.valueOf(line)));
		return line;
	}

	//branchesを先頭から評価し、最初に成立した節だけ実行する。
	private Result executeIfStructure(IfStructure structure, OObject object, OObject target, String message,
			ArrayList<String> scriptList, MemoryData memData, String[] parentparams) throws xTalkException {
		Result r = new Result();
		r.ret = 0;
		for(IfBranch branch : structure.branches) {
			boolean matches = branch.condition == null ||
				conditionIsTrue(Evalution(branch.condition, memData, object, target), "if");
			if(!matches) continue;
			if(branch.nested != null) {
				r = executeIfStructure(branch.nested, object, target, message, scriptList, memData, parentparams);
			}
			else if(branch.inlineScript != null) {
				if(!branch.inlineScript.isEmpty()) {
					ArrayList<String> lines = branch.inlineLines();
					//the statement after then/else is rebuilt from lower-cased words: its unquoted literals keep the case of the if line
					String saveSource = inlineIfSource.get();
					ArrayList<String> saveLines = inlineIfLines.get();
					inlineIfSource.set(statementSource.get());
					inlineIfLines.set(lines);
					try{ r = doScript(object, target, message, lines, 0, lines.size()-1, memData, parentparams, 1); }
					finally{ inlineIfSource.set(saveSource); inlineIfLines.set(saveLines); }
				}
			}
			else if(branch.bodyStart >= 0 && branch.bodyStart <= branch.bodyEnd) {
				r = doScript(object, target, message, scriptList, branch.bodyStart, branch.bodyEnd,
					memData, parentparams, 0);
			}
			break;
		}
		return r;
	}

	//ハンドラの中身を実行
	//objectがnullの場合もある
	//messageがnullの場合もある
	//-1 . error/exit to HyperCard
	//0 .. normal end
	//1 .. pass message
	//2 .. exit repeat
	//3 .. exit handler / return
	//4 .. next repeat
	/** The source line of the statement being run on this thread: an unquoted literal keeps the case it is written in there
	 *  (HyperCard: put HeLLo → "HeLLo"; Myst Preview's create menu File / Options are titled as written). Words are
	 *  lower-cased when a line is split, so the literal's spelling is looked up in its line again. */
	private static final ThreadLocal<String> statementSource = new ThreadLocal<String>();
	/** the statement being run as written (the words keep their case) */
	static String currentStatementSource(){ return statementSource.get(); }
	/** The if line whose one-line then/else statement (inlineIfLines) is being run */
	private static final ThreadLocal<String> inlineIfSource = new ThreadLocal<String>();
	private static final ThreadLocal<ArrayList<String>> inlineIfLines = new ThreadLocal<ArrayList<String>>();

	/** The unquoted literal {@code word} as it is spelt in the statement being run (the first occurrence outside quotes and
	 *  comments, whole words only); the word itself when it is not found there. */
	static String literalCase(String word) {
		String src = statementSource.get();
		int m = word.length();
		if(src==null || m==0 || !(Character.isLetter(word.charAt(0)) || word.charAt(0)=='_')) return word; //_Qlist (HC J-2.3: as written)
		boolean quoted = false;
		for(int i=0; i+m<=src.length(); i++){
			char c = src.charAt(i);
			if(c=='"'){ quoted = !quoted; continue; }
			if(quoted) continue;
			if(c=='-' && i+1<src.length() && src.charAt(i+1)=='-') break;
			if(src.regionMatches(true, i, word, 0, m) && (i==0 || !isLiteralWordChar(src.charAt(i-1))) &&
					(i+m==src.length() || !isLiteralWordChar(src.charAt(i+m))))
				return src.substring(i, i+m);
		}
		return word;
	}
	private static boolean isLiteralWordChar(char c) { return Character.isLetterOrDigit(c) || c=='_'; }
	/** value(text): text is an expression of its own, so an unquoted literal in it keeps the case it has there
	 *  (HyperCard J-2.3: value("Probe") = "Probe") */
	/** The value before the numberFormat of the expression evaluateValueText just evaluated, when that was a computed
	 *  number, else null: value() hands it on raw like a function's return (HC J-2.3: a NAN/INF from value("sqrt(-1)")
	 *  passed as a parameter still computes, umich HypoGraph's plot x,value(thev)) */
	static String lastValueRaw(){ return lastEvalNumeric ? lastEvalRaw : null; }

	static String evaluateValueText(String text, MemoryData memData, OObject object, OObject target) throws xTalkException {
		String outerSource = statementSource.get();
		statementSource.set(text);
		try{ return Evalution(text, memData, object, target); }
		finally{ statementSource.set(outerSource); }
	}

	private Result doScript(OObject object, OObject target, String message, ArrayList<String> scriptList, int start, int end,
			MemoryData memData, String[] parentparams, int mode)
	throws xTalkException
	{
		String outerSource = statementSource.get();
		if(StackSpeed.limited()) StackSpeed.block(); //repeatの1回、ifの分岐、ハンドラ
		try{
			return doScriptLines(object, target, message, scriptList, start, end, memData, parentparams, mode);
		}finally{
			statementSource.set(outerSource); //the calling statement goes on (put f() & Hello)
		}
	}

	private Result doScriptLines(OObject object, OObject target, String message, ArrayList<String> scriptList, int start, int end,
			MemoryData memData, String[] parentparams, int mode)
	throws xTalkException
	{
		if(TTalk.stop){
			throw new xTalkException("user abort.");
		}
		
		int line=start;
		Result result = new Result();
		//エラーを起こした文の行(repeat/ifは走査で行が進むので別に持つ)と、
		//デバッガでエラーの後も続行する場合に再開する行(文またはブロックの最終行)
		int stmtLine=start;
		int resumeLine=start;
		
		/*StringBuilder scr = new StringBuilder(128);
		scr.append("+ ");
		for(int i=start; i<=end; i++){
			scr.append(scriptList.get(i));
			scr.append(" ");
		}
		System.out.println(scr.toString());*/
		
		result.ret=0;

		if(object!=null && object.wrapFlag==false && object.scriptList==scriptList){
			joinContinuationLines(scriptList);
			object.wrapFlag = true;
		}
		
		while(line<=end){
			stmtLine = line;
			resumeLine = line;
			statementSource.set(scriptList==inlineIfLines.get() && inlineIfSource.get()!=null ? inlineIfSource.get() : scriptList.get(line));
			try{ //
				/*String str=scriptList.get(line);
				while(str.length()>0 && 
						(str.charAt(str.length()-1)=='ﾂ' ||
						str.charAt(str.length()-1)=='~') )
				{
					line++;
					if(line>end) break;
					str = str.substring(0,str.length()-1)+" "+scriptList.get(line);
				}
				int spacing1=0;
				while(spacing1<str.length() && (str.charAt(spacing1)==' ' || str.charAt(spacing1)=='　')) spacing1++;
				String[] words = str.substring(spacing1).split(" ");
				if(words.length==0) continue;*/
				ArrayList<String> sList;
				ArrayList<wordType> tList;
				if(object==null || scriptList != object.scriptList || object.stringList==null || object.stringList[line] == null){
					String str=scriptList.get(line);
					ParsedTalkLine[] cachedLines = null;
					ParsedTalkLine cachedLine = null;
					if(object==null || scriptList != object.scriptList){
						if(memData.parsedLines==null) memData.parsedLines = new java.util.IdentityHashMap<>();
						cachedLines = memData.parsedLines.get(scriptList);
						if(cachedLines==null){
							if(memData.parsedLines.size()>=32) memData.parsedLines.clear();
							cachedLines = new ParsedTalkLine[scriptList.size()];
							memData.parsedLines.put(scriptList, cachedLines);
						}
						cachedLine = cachedLines[line];
					}
					/*while(str.length()>0 && 
							(str.charAt(str.length()-1)=='ﾂ' ||
							str.charAt(str.length()-1)=='~') )
					{
						line++;
						if(line>end) break;
						str = str.substring(0,str.length()-1)+" "+scriptList.get(line);
					}*/
					//分解
					if(cachedLine!=null && cachedLine.variableVersion==memData.variableVersion &&
							cachedLine.source.equals(str)){
						sList = cachedLine.words;
						tList = cachedLine.types;
					}else{
						sList = new ArrayList<String>();
						tList  = new ArrayList<wordType>();
						int oldVariableCount = memData.treeset.size();
						fullresolution(str, sList, tList, memData.treeset, true);
						if(memData.treeset.size()!=oldVariableCount) memData.variableVersion++;
						if(cachedLines!=null) cachedLines[line] = new ParsedTalkLine(str, sList, tList, memData.variableVersion);
					}
					//オブジェクト自身のキャッシュには自身のスクリプトだけを書き込む。
					//do/send の文字列は MemoryData の実行単位キャッシュに保持する。
					if(object!=null && scriptList == object.scriptList &&
						object.stringList!=null && line<object.stringList.length){
						object.stringList[line] = sList;
						object.typeList[line] = tList;
					}
				}
				else{
					sList = object.stringList[line];
					tList  = object.typeList[line];
				}
				if(sList.size()==0) {
					line++;
					continue;
				}
				
				//デバッガ(チェックポイント/ステップ/トレース)
				ScriptDebugger.beforeStatement(object, scriptList, line, memData);
				//スタック個別設定の速度制限: 当時のHyperCardでこの文にかかった時間だけ待つ
				if(StackSpeed.limited()) StackSpeed.statement(sList.size());
				
				String str0 = sList.get(0);
				if(str0=="repeat"){
					start=line;
					line=findEndRepeat(object, scriptList, line, end);
					resumeLine = line; //end repeatの行
					
					if(sList.size()<=1 || sList.get(1).startsWith("--") || sList.get(1).equalsIgnoreCase("forever")){
						//repeat [forever]
						while(true){
							result = doScript(object,target,message,scriptList,start+1,line-1,memData,parentparams,0);
							if(result.ret==4) result.ret=0; //next repeat
							else if(result.ret!=0)
								break;
						}
					}
					else if(sList.size()>=6 && sList.get(1).equalsIgnoreCase("for") &&
							sList.get(2).equalsIgnoreCase("each") &&
							(sList.get(3).equalsIgnoreCase("item") || sList.get(3).equalsIgnoreCase("key")) &&
							(sList.get(4).equalsIgnoreCase("in") || sList.get(4).equalsIgnoreCase("of"))){
						String value=Evalution(combine(5,sList.size(),sList,tList),memData,object,target);
						TalkCollection collection=TalkCollection.decode(value);
						boolean items=sList.get(3).equalsIgnoreCase("item");
						if(items!=collection.isArray()) throw new xTalkException(items ? "An array is required" : "A dictionary is required");
						ArrayList<String> values=items ? new ArrayList<String>(collection.items) :
							new ArrayList<String>(collection.entries.keySet());
						for(String eachValue:values){
							setVariable(memData,items ? "it" : "key",eachValue);
							result=doScript(object,target,message,scriptList,start+1,line-1,memData,parentparams,0);
							if(result.ret==4) result.ret=0;
							else if(result.ret!=0) break;
						}
					}
					else if(sList.get(1).equalsIgnoreCase("with")){
						//repeat with xxxx=x to xx / down to
						if(sList.size()<7 || !sList.get(3).equals("=")){
							throw new xTalkException("Cannot understand the arguments to repeat with");
						}
						String mem=sList.get(2);
						boolean down=false;
						int separator=-1;
						for(int next=4; next<sList.size(); next++){
							if(sList.get(next).equalsIgnoreCase("to")){
								separator=next;
								break;
							}
							if(sList.get(next).equalsIgnoreCase("down") && next+1<sList.size() &&
									sList.get(next+1).equalsIgnoreCase("to")){
								down=true;
								separator=next;
								break;
							}
						}
						if(separator<=4) throw new xTalkException("repeat with requires a start value and to");
						int rangeEndStart=separator+(down?2:1);
						if(rangeEndStart>=sList.size()) throw new xTalkException("repeat with requires an end value");
						String startStr = Evalution(combine(4,separator,sList,tList),memData, object, target);
						String endStr = Evalution(combine(rangeEndStart,sList.size(),sList,tList),memData, object, target);
						int current;
						int rangeEnd;
						try{
							//numberFormatが"0.00"のときは"4.00"のように整数値が小数表記で
							//渡ってくるので、値が整数ならそれも受け付ける
							//an empty bound is 0 (HC J-2.3: repeat with i = 1 to y with y empty runs no times; たしざんひきざん's
							//coin buttons before a problem is set)
							current=startStr.trim().isEmpty() ? 0 : wholeNumber(startStr);
							rangeEnd=endStr.trim().isEmpty() ? 0 : wholeNumber(endStr);
						}catch(NumberFormatException e){
							throw new xTalkException("repeat with requires integer bounds");
						}
						while(down ? current>=rangeEnd : current<=rangeEnd){
							setNumberVariable(memData,mem,Integer.toString(current));
							result = doScript(object,target,message,scriptList,start+1,line-1,memData,parentparams,0);
							if(result.ret==4) result.ret=0; //next repeat
							else if(result.ret!=0) break;
							current += down ? -1 : 1;
						}
					}
					else if(sList.get(1).equalsIgnoreCase("while")){
						//repeat while
						String prm="";
						int next=2;
						while(true){
							if(next>=sList.size() || sList.get(next).startsWith("--"))
								break;
							//引用符付きの語は引用符を戻す("," や "x y" が式の中で別の語にならないように)
							prm += " "+(tList.get(next)==wordType.STRING ? "\""+sList.get(next)+"\"" : sList.get(next));
							next++;
						}
						while(conditionIsTrue(Evalution(prm,memData, object, target), "repeat while")){
							result = doScript(object,target,message,scriptList,start+1,line-1,memData,parentparams,0);
							if(result.ret==4) result.ret=0; //next repeat
							else if(result.ret!=0)
								break;
						}
					}
					else if(sList.get(1).equalsIgnoreCase("until")){
						//repeat until
						String prm="";
						int next=2;
						while(true){
							if(next>=sList.size() || sList.get(next).startsWith("--"))
								break;
							//引用符付きの語は引用符を戻す("," や "x y" が式の中で別の語にならないように)
							prm += " "+(tList.get(next)==wordType.STRING ? "\""+sList.get(next)+"\"" : sList.get(next));
							next++;
						}
						while(!conditionIsTrue(Evalution(prm,memData, object, target), "repeat until")){
							result = doScript(object,target,message,scriptList,start+1,line-1,memData,parentparams,0);
							if(result.ret==4) result.ret=0; //next repeat
							else if(result.ret!=0)
								break;
						}
					}
					else {
						//repeat [for] x [times]
						//repeat until
						String prm="";
						int next=1;
						if(next<sList.size() && sList.get(next).equalsIgnoreCase("for"))
							next++;
						while(true){
							if(next>=sList.size() || sList.get(next).startsWith("--") || sList.get(next).equalsIgnoreCase("times"))
								break;
							//引用符付きの語は引用符を戻す("," や "x y" が式の中で別の語にならないように)
							prm += " "+(tList.get(next)==wordType.STRING ? "\""+sList.get(next)+"\"" : sList.get(next));
							next++;
						}
						//HyperCardと同様に繰り返し回数はループ開始時に一度だけ評価する。
						//毎回評価すると、ループ内で回数の元になる値を変更した場合に
						//回数が変わってしまい、無限ループになることもある
						String cntStr = Evalution(prm,memData, object, target);
						int cnt=0;
						int times;
						try{
							times = cntStr.trim().isEmpty() ? 0 : (int)Math.floor(Double.parseDouble(cntStr.trim())); //repeat empty: no times (HC J-2.3)
						}catch(NumberFormatException e){
							throw new xTalkException("The repeat count is not a number: {0}", cntStr);
						}
						while(cnt<times){
							result = doScript(object,target,message,scriptList,start+1,line-1,memData,parentparams,0);
							if(result.ret==4) result.ret=0; //next repeat
							else if(result.ret!=0)
								break;
							cnt++;
						}
					}
					if(result.ret==-1 || result.ret==1 || result.ret==3)
						break;
					result.ret=0;
				} //repeat終わり
				else if(str0=="if"){
					//if文の構造が壊れていて解析できなければ、続行時はブロックの末尾まで飛ばす
					resumeLine = end;
					IfStructure structure = cachedIfStructure(object, scriptList, line, end, sList, tList);
					resumeLine = structure.endLine;
					result = executeIfStructure(structure, object, target, message, scriptList, memData, parentparams);
					if(result.ret!=0) return result;
					line = structure.endLine;
				}
				else if(str0=="exit"){
					if(sList.size()>=2 && sList.get(1).equalsIgnoreCase("repeat")){
						result.ret=2;
						return result;
					}
					if(sList.size()>=2 && 0==sList.get(1).compareToIgnoreCase(message)){
						result.ret=3;
						result.theResult="";
						return result;
					}
					if(sList.size()>=2 && sList.get(1).equalsIgnoreCase("to")){
						if(sList.size()>=3 && sList.get(2).equalsIgnoreCase("hypercard")){
							result.ret=-1;
							return result;
						}
					}
					throw new xTalkException("Cannot understand exit");
				}
				else if(str0=="next"){
					if(sList.size()>=2 && sList.get(1).equalsIgnoreCase("repeat")){
						//if文の中などネストしたdoScriptから呼ばれても外側のrepeatまで
						//伝わるように、専用の戻り値で返す
						result.ret=4;
						return result;
					}
					throw new xTalkException("Cannot understand next");
				}
				else if(str0=="pass"){
					if(sList.size()>=2 && 0==sList.get(1).compareToIgnoreCase(message)){
						result.ret=1;
						return result;
					}
					throw new xTalkException("Cannot understand pass");
				}
				else if(str0=="return"){
					//resultは直前の文のResult(=lastResult)と同じオブジェクトのことがあるので、
					//「return the result」のために式を評価してから新しいResultに入れる
					String returnValue = "";boolean numericReturn = false;
					if(sList.size()>=2){
						//キャッシュされた単語リストはEvalutionで書き換えられるのでコピーして評価する
						ArrayList<String> retList = new ArrayList<String>(sList);
						wordType[] retAry = new wordType[tList.size()];
						tList.toArray(retAry);
						returnValue = Evalution(retList, retAry, 1, retList.size()-1, memData, object, target);
						//a computed number: a function hands its raw value to the calling expression, which keeps the precision and
						//formats it as text (HC 2.4 and J-2.3: return 1/3 → f()*3 = 1, f() & "|" = 0.333333|; return 2^h → 16, not
						//"16.0"); a command's result is its text
						if(lastEvalNumeric && lastEvalRaw!=null) numericReturn = true;
						else if(retList.size()==2 && isRawNumberVariable(memData, sList.get(1).toLowerCase(Locale.ROOT))) numericReturn = true;
						if(numericReturn){
							String raw = lastEvalNumeric && lastEvalRaw!=null ? lastEvalRaw : returnValue;
							if(memData.isFunction) returnValue = raw; else { returnValue = applyNumberFormat(raw); numericReturn = false; }
						}
					}
					result = new Result();
					result.theResult = returnValue;
					result.numeric = numericReturn;
					//returnはハンドラ全体を終了する。if文やrepeat文の中から呼ばれた場合も
					//ネストしたdoScriptを抜けてハンドラまで伝わるようにexit handlerと同じ値を返す
					result.ret=3;
					return result;
				}
				else if(str0=="end"){
					throw new xTalkException("Misplaced end");
				}
				else {
					//通常文の実行
					if(TTalk.stop == true){
						throw new xTalkException("user abort.");
					}
					//外部命令の VM が生きているとき(XWindoid、PlayMOD のような常駐プレーヤ)は、ハンドラが走り続ける間も
					//ときどきそのタイマー・サウンドの後始末を回す(実機の割り込みの代わり。idle と wait では別途回している)
					if(Xcmd68k.hasSessions()) Xcmd68k.pumpIfDue();
					/*if(object==null || scriptList != object.scriptList){
						//System.out.println(">> "+str);
						result = doScriptLine(str, object, target, memData);
					}else{
						if( object.stringList==null || object.stringList[line] == null){
							//分解
							//object.stringList[line] = new ArrayList<String>();
							//object.typeList[line]  = new ArrayList<wordType>();
							//fullresolution(str, object.stringList[line], object.typeList[line], true);
						}
						//System.out.println(">> "+str);

						ArrayList<String> stringList = new ArrayList<String>(object.stringList[line]);

						wordType[] typeAry = new wordType[object.typeList[line].size()];
						for(int i=0; i<object.typeList[line].size(); i++){ //リストより配列に移す
							typeAry[i] = object.typeList[line].get(i);
						}
						
						//実行
						result = CommandExec(stringList, typeAry, object, target, memData);
					}*/
					
					
					ArrayList<String> stringList = new ArrayList<String>(sList);

					wordType[] typeAry = new wordType[tList.size()];
					tList.toArray(typeAry);
					//"put 0 into n else" ⏎ … : the else at the end of a statement is the if block's (trailingElseLine)
					if(stringList.size()>1 && str0!="if" && str0!="else" && typeAry[stringList.size()-1]!=wordType.STRING &&
							stringList.get(stringList.size()-1).equalsIgnoreCase("else")){
						stringList.remove(stringList.size()-1);
						typeAry = java.util.Arrays.copyOf(typeAry, stringList.size());
					}
					/*wordType[] typeAry = new wordType[tList.size()];
					for(int i=0; i<tList.size(); i++){ //リストより配列に移す
						typeAry[i] = tList.get(i);
					}*/

					//実行
					result = CommandExec(stringList, typeAry, object, target, memData, line);
					//a global declaration is no command: the result of the statement before it stays (HyperCard J-2.3, measured;
					//Dartmouth's EditWindow button declares the global it puts "the result" of the XCMD into on the line between)
					if(str0!="global") lastResult = result;
					//呼び出したハンドラの中で exit to HyperCard された(またはgo homeで
					//スタックを閉じた)場合は、HyperCardと同様に呼び出し元のハンドラも
					//そこで終了する。続行すると、移動先のカードに存在しないオブジェクトを
					//参照して無関係なエラーになる
					if(result.ret==-1) return result;
					if(exitingToHyperCard){ result.ret = -1; return result; } //a function's exit to HyperCard was caught on the way
				}
			    line++;
			} catch(xTalkException e){
				//スクリプトエラー発生時の処理。ダイアログで「デバッグ」が選ばれ、
				//デバッガから続行(Go/Step/Trace)されたときだけ戻ってくる
				handleScriptError(e, object, scriptList, stmtLine, memData, mode);
				line = resumeLine+1;
				result = new Result();
				result.ret = 0;
			} catch(RuntimeException e){
				//a Java exception in a statement HyperZebra does not handle: a script error at that statement like any other, not a
				//handler (and an external's SendHCMessage) that silently stops (XCMDs_Pan: parse XFCN, `the soundVolume` in &)
				e.printStackTrace();
				String statement = stmtLine>=0 && stmtLine<scriptList.size() ? scriptList.get(stmtLine).trim() : "";
				handleScriptError(new xTalkException("Cannot interpret {0}", statement), object, scriptList, stmtLine, memData, mode);
				line = resumeLine+1;
				result = new Result();
				result.ret = 0;
			}
		}

		return result;
	}

	/**
	 * スクリプトエラーのダイアログ。Cancel/Scriptなら(TTalk.stopを立てて)例外を投げ直し、
	 * Debugならエラーになった文の位置で一時停止する。デバッガで続行されたときだけ普通に戻る。
	 */
	private void handleScriptError(xTalkException e, OObject object, ArrayList<String> scriptList,
			int line, MemoryData memData, int mode)
	throws xTalkException
	{
		if(e instanceof ExitToHyperCard) throw e; //not an error: the handlers just end
		String statement = "";
		if(line>=0 && line < scriptList.size()) statement=scriptList.get(line).trim();
		System.out.println("Error occurred at:"+statement);
		
		if(mode==1){ //内部呼び出しなので、ここではダイアログを出さず上位の呼び出し元に投げる
			e.printStackTrace();
			throw new xTalkException(e);
		}
		
		if(object!=null) System.out.println("line "+(line+1)+" of "+object.getShortName());

		synchronized (messageList) { messageList.removeIf(message -> !message.keep); }
		
		lastErrorTime = System.currentTimeMillis();
		idleResumeTime = lockErrorDialogs ? 0 : lastErrorTime + 10*1000;
		
		if(TTalk.stop == true){ //cmd+.による強制停止 または エラーによる停止
			throw new xTalkException(e);
		}

		e.printStackTrace();
		
		if(lockErrorDialogs){
			//ダイアログの代わりに errorDialog <エラー文> をカレントカードへ送り、ハンドラを終わらせる(HyperCard)
			if(!inErrorDialog && PCARD.pc!=null && PCARD.pc.stack!=null && PCARD.pc.stack.curCard!=null){
				inErrorDialog = true;
				try{
					ReceiveMessage("errorDialog", new String[]{e.getMessage()==null ? "" : e.getMessage()}, PCARD.pc.stack.curCard, PCARD.pc.stack.curCard, memData);
				}catch(xTalkException ignore){
				}finally{
					inErrorDialog = false;
				}
			}
			TTalk.stop = true;
			throw new xTalkException(e);
		}
		
		//行番号がエディタと対応する(do/sendの文字列ではない)ときだけデバッガに入れる
		boolean canDebug = object!=null && object.scriptList==scriptList && line>=0 && line<scriptList.size();
		boolean hasScript = object != null && object.scriptList!=null && object.scriptList.size()>0;
		if(canDebug){
			//エディタがその行を赤く示す(次にそのスクリプトを保存するか、その位置以前を編集するまで)
			object.lastErrorLine = line;
			object.lastErrorMessage = e.getMessage();
			ScriptEditor.showRuntimeError(object);
		}
		int choice;
		if(errorDialogForTest!=null){
			choice = errorDialogForTest.getAsInt();
		}
		else{
			java.awt.Toolkit.getDefaultToolkit().beep();
			choice = showScriptErrorDialog(e.getMessage(), statement, line, object, hasScript, canDebug);
		}
		if(choice==ERROR_DEBUG && !canDebug) choice = ERROR_CANCEL;
		
		if(choice==ERROR_DEBUG){
			ScriptDebugger.pauseAtError(object, line, memData, e.getMessage());
			return;
		}
		if(choice==ERROR_SCRIPT){
			ScriptEditor.openScriptEditor(PCARD.pc, object, line);
		}
		
		TTalk.stop = true;//無駄なダイアログを発生させない
		
		throw new xTalkException(e);
	}

	static final int ERROR_CANCEL = 0;
	static final int ERROR_SCRIPT = 1;
	static final int ERROR_DEBUG = 2;
	/** テスト用: ダイアログを出す代わりにここから選択を得る */
	static java.util.function.IntSupplier errorDialogForTest;

	/** エラーダイアログをEDT上で表示し、選ばれたボタンを返す */
	static int showScriptErrorDialog(String errorMessage, String statement, int line, OObject object,
			boolean hasScript, boolean canDebug)
	{
		final int[] choice = { ERROR_CANCEL };
		Runnable show = new Runnable() {
			public void run() {
				choice[0] = showScriptErrorDialogOnEdt(errorMessage, statement, line, object, hasScript, canDebug);
			}
		};
		if(SwingUtilities.isEventDispatchThread()){
			show.run();
		}
		else{
			try{
				SwingUtilities.invokeAndWait(show);
			}catch(Exception ex){
				ex.printStackTrace();
			}
		}
		return choice[0];
	}

	/** Shared by the dialog and headless checks, so details are retained in every language. */
	static String scriptErrorText(String errorMessage, String statement, int line, OObject object){
		StringBuilder text = new StringBuilder(International.t("Script Error"));
		if(errorMessage!=null && errorMessage.length()>0){
			text.append(": ").append(errorMessage);
		}
		if(statement!=null && statement.length()>0){
			text.append("\n\n").append(statement);
		}
		if(object!=null){
			text.append("\n").append(International.t("line {0} of {1}", line+1, object.getShortName()));
		}
		return text.toString();
	}

	private static int showScriptErrorDialogOnEdt(String errorMessage, String statement, int line, OObject object,
			boolean hasScript, boolean canDebug)
	{
		International intl = PCARD.pc.intl;
		String text = scriptErrorText(errorMessage, statement, line, object);
		if(!hasScript){
			Object[] options = { intl.getDialogText("OK") };
			JOptionPane.showOptionDialog(PCARD.pc, text, International.t("Script Error"),
					JOptionPane.YES_OPTION, JOptionPane.WARNING_MESSAGE, null, options, options[0]);
			return ERROR_CANCEL;
		}
		String cancel = intl.getDialogText("Cancel");
		String script = intl.getDialogText("Script");
		String debug = intl.getDialogText("Debug");
		Object[] options = canDebug ? new Object[]{ cancel, script, debug } : new Object[]{ cancel, script };
		int retValue = JOptionPane.showOptionDialog(PCARD.pc, text, International.t("Script Error"),
				JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE, null, options, options[0]);
		if(retValue==1) return ERROR_SCRIPT;
		if(retValue==2) return ERROR_DEBUG;
		return ERROR_CANCEL;
	}

	static String evaluateSendMessage(ArrayList<String> stringList, wordType[] typeAry,
			int start, int end, MemoryData memData, OObject object, OObject target)
			throws xTalkException {
		// HyperTalk permits `send DATE`: when a single token is also the name of a
		// built-in function, it is the message name here, not a function call.
		if(start==end && start>=0 && start<stringList.size() &&
				(typeAry[start]==wordType.FUNC || typeAry[start]==wordType.THE_FUNC)){
			return stringList.get(start);
		}
		return Evalution(stringList, typeAry, start, end, memData, object, target);
	}
	
	private static String combine(int start, int end, ArrayList<String> stringList, ArrayList<wordType> typeList){
		StringBuilder str = new StringBuilder(32);
		
		for(int i=start; i<end; i++){
			//an unquoted number stays unquoted: `if field 1 = field 2` is the first field, not a field NAMED "1" (QuickPick's
			//49 hidden card fields "1".."49" made NewSet loop forever at openStack); a quoted "1" is the quoted-literal token
			if(typeList.get(i) == wordType.STRING && isOrdinalNumber(stringList.get(i)) && !isQuotedNumberLiteral(stringList.get(i))){
				str.append(stringList.get(i)).append(" ");
			}
			else if(typeList.get(i) == wordType.STRING){
				str.append("\"");
				str .append(stringList.get(i));
				str.append("\" ");
			} else {
				str .append(stringList.get(i));
				str.append(" ");
			}
		}
		
		return str.toString();
	}

	private static void resolution(String script, ArrayList<String> stringList, ArrayList<wordType> typeList, boolean isCmd)
	{
		ScriptArea.checkWordsLine(script, stringList, typeList, isCmd, false);
		for(int j=0; j<typeList.size(); j++){
			if(typeList.get(j)==TTalk.wordType.COMMENT){
				typeList.remove(j);
				stringList.remove(j);
				break;
			}
		}
		dropNameOfAfterProperty(stringList, typeList);
		chunkInAsOf(stringList, typeList);
		dropTheBeforeOrdinalObject(stringList, typeList);
	}

	private static final java.util.Set<String> ORDINAL_OBJECT_WORDS = java.util.Set.of("card", "cd", "cards", "cds", "background",
		"bkgnd", "bg", "field", "fld", "button", "btn", "part");
	/**
	 * "the last card field" is "last card field" (HCI'95 Postits: put defaultContents(name) into the last card field / set the
	 * name of the last card field to name): a "the" before an ordinal and an object word only reads well.
	 */
	private static void dropTheBeforeOrdinalObject(ArrayList<String> stringList, ArrayList<wordType> typeList) {
		for(int j=0; j+2<stringList.size(); j++){
			if(typeList.get(j)==wordType.STRING || typeList.get(j+1)==wordType.STRING || typeList.get(j+2)==wordType.STRING) continue;
			if(!"the".equalsIgnoreCase(stringList.get(j)) || !isRelativeChunkSpecifier(stringList.get(j+1))) continue;
			//set the textFont of the last word of line 2 of fld "x" (AOL How Old Are You?): a chunk after "of" reads the same way
			boolean chunkAfterOf = j>0 && typeList.get(j-1)!=wordType.STRING && "of".equalsIgnoreCase(stringList.get(j-1)) && isChunkWord(stringList.get(j+2));
			if(!ORDINAL_OBJECT_WORDS.contains(stringList.get(j+2).toLowerCase(Locale.ROOT)) && !chunkAfterOf) continue;
			stringList.remove(j); typeList.remove(j);
		}
	}

	/**
	 * HyperCard J-2.3 takes "in" for "of" after a chunk: {@code line 2 in fld 1}, {@code the number of lines in v},
	 * {@code put "Z" into word 2 in v}, {@code delete line 1 in v}. 全国主要市外局番2.3's Up button does
	 * {@code find line REG in bg fld "DATA"}: HyperCard finds that line's text in any field (probes G In 01-16), HyperZebra
	 * stopped with "2がわかりません". The "in" where a chunk's number ends becomes "of"; an "in" after a value that is no chunk
	 * number stays ({@code is in}, {@code find "x" in fld 1}, {@code in a new window}), and so does the find mode word
	 * ({@code find word "x" in fld 1}).
	 */
	private static void chunkInAsOf(ArrayList<String> words, ArrayList<wordType> types) {
		boolean any = false;
		for(int k=0; k<words.size() && !any; k++) any = types.get(k)!=wordType.STRING && words.get(k).equalsIgnoreCase("in");
		if(!any) return;
		wordType[] typeAry = null;
		for(int j=0; j+1<words.size(); j++){
			if(types.get(j)==wordType.STRING || !isChunkWord(words.get(j))) continue;
			if(j>0 && types.get(j-1)!=wordType.STRING && (words.get(j-1).equalsIgnoreCase("find") || words.get(j-1).equalsIgnoreCase("international")) &&
					FIND_MODE_WORDS.contains(words.get(j).toLowerCase(Locale.ROOT))) continue; //find word "x" in fld 1: the mode

			int depth = 0;
			for(int k=j+1; k<words.size(); k++){
				wordType t = types.get(k);
				if(t==wordType.LBRACKET || t==wordType.LFUNC){ depth++; continue; }
				if(t==wordType.RBRACKET || t==wordType.RFUNC){ if(--depth<0) break; continue; }
				if(depth>0 || t==wordType.STRING) continue;
				String w = words.get(k).toLowerCase(Locale.ROOT);
				if(w.equals("in")){ words.set(k, "of"); break; }
				if(w.equals("of")){
					if(typeAry==null) typeAry = types.toArray(new wordType[0]);
					if(k>j+1 && ofBelongsToExpression(words, typeAry, k, j+1)) continue; //line number of lines in v
					break;
				}
				if(CHUNK_NUMBER_ENDS.contains(w)) break;
			}
		}
	}
	private static final java.util.Set<String> FIND_MODE_WORDS = java.util.Set.of("word", "words", "chars", "characters");
	private static final java.util.Set<String> CHUNK_NUMBER_ENDS = java.util.Set.of("is", "isn't", "contains", "into", "after",
		"before", "then", "else", "and", "or", "&", "&&", ",", "=", "<", ">", "<=", ">=", "<>", "≠", "≤", "≥", "by", "with", "from", "at");

	private static final java.util.Set<String> NAME_LIKE_PROPERTIES = java.util.Set.of(
		"name", "short", "long", "abbr", "abbrev", "abbreviated", "english", "number", "id");

	/**
	 * HyperCard J-2.3 reads "the visible of name of cd btn 1" as "the visible of cd btn 1" (HyperPiece 2「オブジェクトのプロパティ１」
	 * の Show Name 行。showName ではなく visible が返る)。プロパティ名の "of" の直後の "name of" を読み飛ばす。
	 */
	private static void dropNameOfAfterProperty(ArrayList<String> stringList, ArrayList<wordType> typeList) {
		for(int j=2; j+2<stringList.size(); j++){
			if(typeList.get(j)==wordType.STRING || typeList.get(j-1)==wordType.STRING || typeList.get(j-2)==wordType.STRING) continue;
			if(!"name".equalsIgnoreCase(stringList.get(j)) || !"of".equalsIgnoreCase(stringList.get(j+1)) || !"of".equalsIgnoreCase(stringList.get(j-1))) continue;
			String prop = stringList.get(j-2).toLowerCase(Locale.ROOT);
			if(propertySet==null || !propertySet.contains(prop) || NAME_LIKE_PROPERTIES.contains(prop)) continue;
			stringList.remove(j); typeList.remove(j);
			stringList.remove(j); typeList.remove(j);
		}
	}
	
	private static void fullresolution(String script, ArrayList<String> stringList, ArrayList<wordType> typeList, TreeSet<String> treeSet, boolean isCmd)
	{
		//同じ文字列の字句解析結果は、結果を左右する状態(単語が変数として宣言済みか、スタックの XCMD/XFCN)が
		//同じなら同じなので使い回す。if の条件、repeat while、do/send の文字列、add の書き換えなどは実行のたびにここを通る
		Rsrc rsrc = (PCARD.pc!=null && PCARD.pc.stack!=null) ? PCARD.pc.stack.rsrc : null;
		int xcmdGeneration = Rsrc.xcmdGeneration;
		java.util.concurrent.ConcurrentHashMap<String,TokenizedLine> cache = isCmd ? commandTokenCache : expressionTokenCache;
		TokenizedLine cached = cache.get(script);
		if(cached!=null && cached.matches(treeSet, rsrc, xcmdGeneration)){
			java.util.Collections.addAll(stringList, cached.words);
			java.util.Collections.addAll(typeList, cached.types);
			if(treeSet!=null) for(String added : cached.addedVariables) treeSet.add(added);
			return;
		}
		
		resolution(script, stringList, typeList, isCmd);
		
		//checkWordsLine2 が変数の集合を見るのは X の単語が宣言済みかどうかだけなので、解析前のその状態を記録する
		ArrayList<String> candidates = new ArrayList<String>();
		for(int i=0; i<stringList.size(); i++){
			if(typeList.get(i)==wordType.X && !candidates.contains(stringList.get(i))) candidates.add(stringList.get(i));
		}
		boolean[] known = new boolean[candidates.size()];
		if(treeSet!=null) for(int i=0; i<known.length; i++) known[i] = treeSet.contains(candidates.get(i));
		
		StringBuilder handler = new StringBuilder("");
		TreeSet<String> varSet;
		if(treeSet!=null) varSet = treeSet;
		else varSet = new TreeSet<String>();
		ScriptArea.checkWordsLine2(script, stringList, typeList, isCmd, handler, varSet);
		
		//on/function/end ハンドラ行は変数の集合を空にすることがあるので覚えない
		if(typeList.contains(wordType.ON_HAND) || typeList.contains(wordType.ON_FUNC) || typeList.contains(wordType.END_HAND)) return;
		ArrayList<String> added = new ArrayList<String>();
		for(int i=0; i<known.length; i++){
			if(!known[i] && varSet.contains(candidates.get(i))) added.add(candidates.get(i));
		}
		if(cache.size() >= TOKEN_CACHE_LIMIT) cache.clear();
		cache.put(script, new TokenizedLine(stringList.toArray(new String[0]), typeList.toArray(new wordType[0]),
				candidates.toArray(new String[0]), known, added.toArray(new String[0]), rsrc, xcmdGeneration));
	}
	
	/** fullresolution の結果。words/types は共有されるので、使う側はリストへ写してから書き換える */
	private static final class TokenizedLine {
		final String[] words;
		final wordType[] types;
		/** 解析前に変数の集合に入っていたかを見た単語(X の単語)と、そのときの結果 */
		final String[] candidates;
		final boolean[] known;
		/** 解析で変数の集合に加わった単語(put ... into x、global x など)。再利用するときにも加える */
		final String[] addedVariables;
		final Rsrc rsrc;
		final int xcmdGeneration;

		TokenizedLine(String[] words, wordType[] types, String[] candidates, boolean[] known,
				String[] addedVariables, Rsrc rsrc, int xcmdGeneration) {
			this.words = words;
			this.types = types;
			this.candidates = candidates;
			this.known = known;
			this.addedVariables = addedVariables;
			this.rsrc = rsrc;
			this.xcmdGeneration = xcmdGeneration;
		}

		boolean matches(TreeSet<String> treeSet, Rsrc currentRsrc, int currentXcmdGeneration) {
			if(rsrc != currentRsrc || xcmdGeneration != currentXcmdGeneration) return false;
			for(int i=0; i<candidates.length; i++){
				boolean nowKnown = treeSet != null && treeSet.contains(candidates[i]);
				if(nowKnown != known[i]) return false;
			}
			return true;
		}
	}
	private static final int TOKEN_CACHE_LIMIT = 8192;
